-- 000001_baseline.sql — consolidated schema baseline.
--
-- Squashed from migrations 000002..000148 (pre-2026-09 history). Generated by
-- pg_dump --schema-only --no-owner --no-privileges against a fresh migrate-up,
-- then de-qualified (no schema prefix) so it still applies inside the
-- throwaway schema the integration tests use. Privileges live in the app-role
-- migration; reference data lives in 000002_seed.

-- Function bodies below are dumped in definition order and may reference tables
-- created later in this file; keep validation off while the baseline loads.
-- SET LOCAL: scoped to the migration runner's transaction only.
SET LOCAL check_function_bodies = false;

