--
-- Name: allocate_commercial_document_number(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION allocate_commercial_document_number(p_company_id uuid, p_document_type_code text, p_sequence_year integer) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    allocated bigint;
    prefix text;
BEGIN
    IF p_sequence_year < 2000 OR p_sequence_year > 9999 THEN
        RAISE EXCEPTION 'commercial document sequence year is invalid' USING ERRCODE = '22023';
    END IF;
    INSERT INTO commercial_document_sequences(company_id, document_type_code, sequence_year)
    VALUES (p_company_id, p_document_type_code, p_sequence_year)
    ON CONFLICT (company_id, document_type_code, sequence_year) DO NOTHING;
    UPDATE commercial_document_sequences
       SET next_value = next_value + 1, updated_at = now()
     WHERE company_id = p_company_id
       AND document_type_code = p_document_type_code
       AND sequence_year = p_sequence_year
    RETURNING next_value - 1 INTO allocated;
    prefix := CASE p_document_type_code
        WHEN 'SALES_QUOTE' THEN 'TKL'
        WHEN 'SALES_ORDER' THEN 'SIP'
        WHEN 'SALES_DELIVERY' THEN 'IRS'
        WHEN 'SALES_INVOICE' THEN 'FTR'
        WHEN 'SALES_RETURN_INVOICE' THEN 'IAD'
        WHEN 'PURCHASE_ORDER' THEN 'ASIP'
        WHEN 'PURCHASE_DELIVERY' THEN 'AIRS'
        WHEN 'PURCHASE_INVOICE' THEN 'AFTR'
        WHEN 'PURCHASE_RETURN_INVOICE' THEN 'AIAD'
        ELSE 'BEL'
    END;
    RETURN prefix || '-' || p_sequence_year::text || '-' || lpad(allocated::text, 6, '0');
END;
$$;

--
-- Name: allocate_document_number(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION allocate_document_number(p_company_id uuid, p_document_type_code text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
    allocated bigint;
BEGIN
    INSERT INTO document_sequences(company_id, document_type_code, next_number)
    VALUES (p_company_id, p_document_type_code, 2)
    ON CONFLICT (company_id, document_type_code)
    DO UPDATE SET next_number = document_sequences.next_number + 1,
                  updated_at = now()
    RETURNING next_number - 1 INTO allocated;
    RETURN allocated;
END;
$$;

--
-- Name: apply_inventory_serial_movement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION apply_inventory_serial_movement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    old_status text;
BEGIN
    IF NEW.serial_id IS NULL THEN
        RETURN NEW;
    END IF;
    SELECT status INTO old_status FROM serial_numbers
     WHERE company_id = NEW.company_id AND id = NEW.serial_id FOR UPDATE;
    IF NEW.direction = 'IN' THEN
        UPDATE serial_numbers
           SET status = 'IN_STOCK', active_warehouse_id = NEW.warehouse_id,
               active_location_id = NEW.location_id, updated_at = now()
         WHERE company_id = NEW.company_id AND id = NEW.serial_id;
    ELSE
        UPDATE serial_numbers
           SET status = 'DISPATCHED', active_warehouse_id = NULL,
               active_location_id = NULL, updated_at = now()
         WHERE company_id = NEW.company_id AND id = NEW.serial_id;
    END IF;
    INSERT INTO serial_number_events(
        id, company_id, serial_id, movement_id, from_status, to_status,
        from_warehouse_id, to_warehouse_id, occurred_at)
    SELECT NEW.id, NEW.company_id, NEW.serial_id, NEW.id,
           old_status,
           CASE WHEN NEW.direction = 'IN' THEN 'IN_STOCK' ELSE 'DISPATCHED' END,
           CASE WHEN NEW.direction = 'OUT' THEN NEW.warehouse_id ELSE NULL END,
           CASE WHEN NEW.direction = 'IN' THEN NEW.warehouse_id ELSE NULL END,
           NEW.posted_at;
    RETURN NEW;
END;
$$;

--
-- Name: apply_inventory_stock_projection(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION apply_inventory_stock_projection() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    projection_id uuid;
    current_quantity numeric(24,8);
    reserved numeric(24,8);
    policy text;
    delta numeric(24,8) := NEW.quantity_delta;
    lock_key text := NEW.company_id::text || ':' || NEW.warehouse_id::text || ':' ||
        NEW.product_id::text || ':' || COALESCE(NEW.variant_id::text, '-') || ':' ||
        COALESCE(NEW.location_id::text, '-') || ':' || COALESCE(NEW.lot_id::text, '-') || ':' ||
        COALESCE(NEW.serial_id::text, '-');
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended(lock_key, 731));
    SELECT id, physical_quantity, reserved_quantity
      INTO projection_id, current_quantity, reserved
      FROM stock_positions
     WHERE company_id = NEW.company_id AND warehouse_id = NEW.warehouse_id
       AND product_id = NEW.product_id
       AND variant_id IS NOT DISTINCT FROM NEW.variant_id
       AND location_id IS NOT DISTINCT FROM NEW.location_id
       AND lot_id IS NOT DISTINCT FROM NEW.lot_id
       AND serial_id IS NOT DISTINCT FROM NEW.serial_id
     FOR UPDATE;
    IF projection_id IS NULL THEN
        current_quantity := 0;
        reserved := 0;
    END IF;
    SELECT COALESCE(negative_stock_policy, 'BLOCK') INTO policy
      FROM inventory_company_policies WHERE company_id = NEW.company_id;
    IF current_quantity + delta < 0 AND COALESCE(policy, 'BLOCK') = 'BLOCK' THEN
        RAISE EXCEPTION 'INSUFFICIENT_STOCK' USING ERRCODE = '23514';
    END IF;
    IF projection_id IS NULL THEN
        INSERT INTO stock_positions(
            id, company_id, warehouse_id, location_id, product_id, variant_id,
            lot_id, serial_id, physical_quantity, reserved_quantity)
        VALUES (md5(lock_key || NEW.id::text)::uuid, NEW.company_id, NEW.warehouse_id, NEW.location_id,
                NEW.product_id, NEW.variant_id, NEW.lot_id, NEW.serial_id,
                delta, 0);
    ELSE
        UPDATE stock_positions
           SET physical_quantity = physical_quantity + delta, updated_at = now()
         WHERE company_id = NEW.company_id AND id = projection_id;
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: apply_stock_cost_layer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION apply_stock_cost_layer() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    remaining numeric(24,8) := NEW.quantity;
    layer record;
    consumed numeric(24,8);
    layer_id uuid;
    company_base_currency char(3);
    resolved_base_cost numeric(24,8);
BEGIN
    IF NEW.direction = 'IN' THEN
        SELECT base_currency INTO company_base_currency FROM companies WHERE id = NEW.company_id;
        layer_id := md5(NEW.company_id::text || ':' || NEW.id::text)::uuid;

        IF NEW.unit_cost IS NOT NULL AND NEW.currency IS NOT NULL THEN
            IF NEW.currency = company_base_currency THEN
                resolved_base_cost := NEW.unit_cost;
            ELSE
                resolved_base_cost := NEW.unit_cost / NEW.exchange_rate_snapshot;
            END IF;
            INSERT INTO stock_cost_layers(
                id, company_id, warehouse_id, product_id, variant_id, lot_id,
                source_movement_id, quantity, remaining_quantity, unit_cost, currency,
                is_provisional, base_unit_cost, base_currency)
            VALUES (
                layer_id, NEW.company_id, NEW.warehouse_id, NEW.product_id,
                NEW.variant_id, NEW.lot_id, NEW.id, NEW.quantity, NEW.quantity,
                NEW.unit_cost, NEW.currency, false, resolved_base_cost, company_base_currency)
            ON CONFLICT (company_id, source_movement_id) DO NOTHING;
        ELSE
            -- A movement without a cost is still valid stock; it must still
            -- open a layer (zero-valued, provisional) so the layer total
            -- never falls behind the physical ledger, and it must leave a
            -- record that valuation is incomplete for this position.
            INSERT INTO stock_cost_layers(
                id, company_id, warehouse_id, product_id, variant_id, lot_id,
                source_movement_id, quantity, remaining_quantity, unit_cost, currency,
                is_provisional, base_unit_cost, base_currency)
            VALUES (
                layer_id, NEW.company_id, NEW.warehouse_id, NEW.product_id,
                NEW.variant_id, NEW.lot_id, NEW.id, NEW.quantity, NEW.quantity,
                0, company_base_currency, true, 0, company_base_currency)
            ON CONFLICT (company_id, source_movement_id) DO NOTHING;
            INSERT INTO stock_cost_unpriced_events(id, company_id, event_type, movement_id, layer_id, quantity)
            VALUES (md5(NEW.company_id::text || ':' || NEW.id::text || ':unpriced')::uuid,
                    NEW.company_id, 'UNPRICED_RECEIPT', NEW.id, layer_id, NEW.quantity);
        END IF;
        RETURN NEW;
    END IF;

    -- Match the lot when the outbound movement is lot-specific.  For a
    -- lot-agnostic dispatch, consume all lots in FIFO order.
    FOR layer IN
        SELECT id, remaining_quantity, unit_cost, currency, base_unit_cost, base_currency
          FROM stock_cost_layers
         WHERE company_id = NEW.company_id
           AND warehouse_id = NEW.warehouse_id
           AND product_id = NEW.product_id
           AND variant_id IS NOT DISTINCT FROM NEW.variant_id
           AND (NEW.lot_id IS NULL OR lot_id IS NOT DISTINCT FROM NEW.lot_id)
           AND remaining_quantity > 0
         ORDER BY created_at, id
         FOR UPDATE
    LOOP
        EXIT WHEN remaining <= 0;
        consumed := LEAST(remaining, layer.remaining_quantity);
        IF consumed <= 0 THEN
            CONTINUE;
        END IF;
        UPDATE stock_cost_layers
           SET remaining_quantity = remaining_quantity - consumed
         WHERE company_id = NEW.company_id AND id = layer.id;
        INSERT INTO stock_cost_consumptions(
            id, company_id, movement_id, layer_id, quantity, unit_cost, currency,
            base_unit_cost, base_currency)
        VALUES (
            md5(NEW.company_id::text || ':' || NEW.id::text || ':' || layer.id::text)::uuid,
            NEW.company_id, NEW.id, layer.id, consumed, layer.unit_cost,
            layer.currency, layer.base_unit_cost, layer.base_currency);
        remaining := remaining - consumed;
    END LOOP;

    IF remaining > 0 THEN
        -- The physical ledger allowed this dispatch but the cost-layer
        -- projection could not find enough remaining quantity to match it.
        -- This must never happen once every IN movement opens a layer (see
        -- above), but it is recorded rather than silently dropped so a
        -- pre-existing divergence stays visible and reconcilable.
        INSERT INTO stock_cost_unpriced_events(id, company_id, event_type, movement_id, layer_id, quantity)
        VALUES (md5(NEW.company_id::text || ':' || NEW.id::text || ':shortfall')::uuid,
                NEW.company_id, 'UNPRICED_CONSUMPTION', NEW.id, NULL, remaining);
    END IF;

    RETURN NEW;
END;
$$;

--
-- Name: enforce_asset_assignment_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION enforce_asset_assignment_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='DELETE' THEN
        RAISE EXCEPTION 'asset assignments are never deleted' USING ERRCODE='55000',CONSTRAINT='asset_assignments_no_delete';
    END IF;
    IF OLD.returned_at IS NOT NULL THEN
        RAISE EXCEPTION 'returned asset assignments are immutable' USING ERRCODE='55000',CONSTRAINT='asset_assignments_returned_immutable';
    END IF;
    IF NEW.company_id<>OLD.company_id OR NEW.id<>OLD.id OR NEW.asset_id<>OLD.asset_id OR
       NEW.employee_id<>OLD.employee_id OR NEW.assigned_at<>OLD.assigned_at OR
       NEW.assigned_by<>OLD.assigned_by OR NEW.actor_snapshot<>OLD.actor_snapshot OR
       NEW.assignment_note<>OLD.assignment_note THEN
        RAISE EXCEPTION 'only an asset return may update an active assignment' USING ERRCODE='55000',CONSTRAINT='asset_assignments_return_only';
    END IF;
    RETURN NEW;
END; $$;

--
-- Name: enforce_commercial_allocation_capacity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION enforce_commercial_allocation_capacity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    source_base numeric;
    already_allocated numeric;
BEGIN
    -- Only a CONSUMED allocation binds the source line. A RESERVED row (draft
    -- target) is advisory and never blocks another document.
    IF NEW.status <> 'CONSUMED' THEN
        RETURN NEW;
    END IF;

    SELECT base_quantity INTO source_base
      FROM commercial_line_registry
     WHERE company_id = NEW.company_id AND line_id = NEW.source_line_id;
    IF source_base IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT COALESCE(SUM(base_quantity), 0) INTO already_allocated
      FROM commercial_line_allocations
     WHERE company_id = NEW.company_id
       AND source_line_id = NEW.source_line_id
       AND allocation_type = NEW.allocation_type
       AND status = 'CONSUMED'
       AND (TG_OP = 'INSERT' OR id <> NEW.id);

    IF already_allocated + NEW.base_quantity > source_base + 1e-9 THEN
        RAISE EXCEPTION 'commercial allocation exceeds source line capacity (% + % > %)',
            already_allocated, NEW.base_quantity, source_base
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: enforce_commercial_header_immutability(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION enforce_commercial_header_immutability() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    allowed boolean := false;
BEGIN
    IF TG_OP = 'DELETE' THEN
        IF OLD.status <> 'DRAFT' THEN
            RAISE EXCEPTION 'posted commercial documents are immutable' USING ERRCODE = '55000';
        END IF;
        RETURN OLD;
    END IF;

    IF OLD.status = 'DRAFT' THEN
        IF TG_TABLE_NAME = 'sales_quotes' THEN
            allowed := NEW.status IN ('DRAFT', 'SENT');
        ELSIF TG_TABLE_NAME = 'sales_orders' THEN
            allowed := NEW.status IN ('DRAFT', 'CONFIRMED');
        ELSIF TG_TABLE_NAME IN ('sales_dispatches', 'sales_invoices', 'sales_returns') THEN
            allowed := NEW.status IN ('DRAFT', 'POSTED');
        END IF;
        IF NOT allowed THEN
            RAISE EXCEPTION 'invalid commercial document state transition' USING ERRCODE = '55000';
        END IF;
        IF NEW.status = 'POSTED' AND NEW.posted_at IS NULL THEN
            RAISE EXCEPTION 'posted commercial documents require posted_at' USING ERRCODE = '23514';
        END IF;
        IF NEW.status <> 'POSTED' AND NEW.posted_at IS NOT NULL THEN
            RAISE EXCEPTION 'unposted commercial documents cannot have posted_at' USING ERRCODE = '23514';
        END IF;
        IF NEW.status <> 'CANCELLED' AND
           (NEW.cancelled_at IS NOT NULL OR NULLIF(btrim(COALESCE(NEW.cancellation_reason, '')), '') IS NOT NULL) THEN
            RAISE EXCEPTION 'cancellation details require a cancelled document' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;

    IF OLD.status = 'CANCELLED' THEN
        RAISE EXCEPTION 'cancelled commercial documents are immutable' USING ERRCODE = '55000';
    END IF;

    IF NEW.company_id <> OLD.company_id OR NEW.document_id <> OLD.document_id OR
       NEW.document_no <> OLD.document_no OR NEW.branch_id <> OLD.branch_id OR
       NEW.default_warehouse_id IS DISTINCT FROM OLD.default_warehouse_id OR
       NEW.party_id <> OLD.party_id OR NEW.document_date <> OLD.document_date OR
       NEW.due_date IS DISTINCT FROM OLD.due_date OR NEW.valid_until IS DISTINCT FROM OLD.valid_until OR
       NEW.currency_code <> OLD.currency_code OR NEW.exchange_rate <> OLD.exchange_rate OR
       NEW.notes <> OLD.notes OR NEW.source_kind <> OLD.source_kind OR
       NEW.source_document_id IS DISTINCT FROM OLD.source_document_id OR
       NEW.subtotal <> OLD.subtotal OR NEW.discount_total <> OLD.discount_total OR
       NEW.tax_total <> OLD.tax_total OR NEW.withholding_total <> OLD.withholding_total OR
       NEW.grand_total <> OLD.grand_total OR NEW.payable_total <> OLD.payable_total OR
       NEW.created_by <> OLD.created_by OR NEW.created_at <> OLD.created_at OR
       NEW.finance_posting_id IS DISTINCT FROM OLD.finance_posting_id OR
       NEW.post_idempotency_key IS DISTINCT FROM OLD.post_idempotency_key OR
       NEW.posted_at IS DISTINCT FROM OLD.posted_at OR
       NEW.version <> OLD.version + 1 THEN
        RAISE EXCEPTION 'posted commercial documents are immutable; only a state transition is allowed' USING ERRCODE = '55000';
    END IF;

    IF TG_TABLE_NAME = 'sales_quotes' THEN
        allowed := NEW.status = OLD.status OR
            (OLD.status = 'SENT' AND NEW.status IN ('ACCEPTED', 'REJECTED'));
    ELSIF TG_TABLE_NAME = 'sales_orders' THEN
        -- Fulfillment projection may move in either direction while OPEN.
        allowed := NEW.status IN ('CONFIRMED', 'PARTIALLY_FULFILLED', 'FULFILLED', 'CANCELLED');
    ELSE
        allowed := NEW.status = OLD.status OR
            (OLD.status = 'POSTED' AND NEW.status = 'CANCELLED');
    END IF;
    IF NOT allowed THEN
        RAISE EXCEPTION 'invalid commercial document state transition' USING ERRCODE = '55000';
    END IF;

    IF NEW.status = 'POSTED' AND NEW.posted_at IS NULL THEN
        RAISE EXCEPTION 'posted commercial documents require posted_at' USING ERRCODE = '23514';
    END IF;
    IF NEW.status = 'CANCELLED' THEN
        IF NEW.cancelled_at IS NULL OR btrim(COALESCE(NEW.cancellation_reason, '')) = '' THEN
            RAISE EXCEPTION 'cancelled commercial documents require a reason' USING ERRCODE = '23514';
        END IF;
    ELSIF NEW.cancelled_at IS DISTINCT FROM OLD.cancelled_at OR
          NEW.cancellation_reason IS DISTINCT FROM OLD.cancellation_reason THEN
        RAISE EXCEPTION 'cancellation details are immutable' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: enforce_document_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION enforce_document_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.status = 'DRAFT' AND NEW.status IN ('DRAFT', 'POSTED') THEN
        RETURN NEW;
    END IF;
    IF OLD.status = 'POSTED' AND NEW.status = 'CANCELLED' THEN
        IF NEW.document_type_code <> OLD.document_type_code OR
           NEW.document_no <> OLD.document_no OR NEW.company_id <> OLD.company_id OR
           NEW.branch_id <> OLD.branch_id OR NEW.warehouse_id IS DISTINCT FROM OLD.warehouse_id OR
           NEW.party_id <> OLD.party_id OR NEW.document_date <> OLD.document_date OR
           NEW.due_date IS DISTINCT FROM OLD.due_date OR NEW.currency_code <> OLD.currency_code OR
           NEW.exchange_rate <> OLD.exchange_rate OR NEW.notes <> OLD.notes OR
           NEW.subtotal <> OLD.subtotal OR NEW.discount_total <> OLD.discount_total OR
           NEW.tax_total <> OLD.tax_total OR NEW.grand_total <> OLD.grand_total OR
           NEW.posted_at <> OLD.posted_at OR NEW.version <> OLD.version + 1 THEN
            RAISE EXCEPTION 'posted documents are immutable; cancel is the only allowed transition' USING ERRCODE = '55000';
        END IF;
        RETURN NEW;
    END IF;
    RAISE EXCEPTION 'invalid document status transition' USING ERRCODE = '55000';
END;
$$;

--
-- Name: enforce_finance_account_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION enforce_finance_account_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.account_type IS DISTINCT FROM OLD.account_type OR
       NEW.currency IS DISTINCT FROM OLD.currency THEN
        RAISE EXCEPTION 'finance account type and currency are immutable'
            USING ERRCODE = '23514', CONSTRAINT = 'finance_account_identity_immutable';
    END IF;
    IF NEW.branch_id IS DISTINCT FROM OLD.branch_id AND EXISTS (
        SELECT 1 FROM finance_account_movements m
        WHERE m.company_id = OLD.company_id AND m.account_id = OLD.id
    ) THEN
        RAISE EXCEPTION 'finance account branch is immutable after first movement'
            USING ERRCODE = '23514', CONSTRAINT = 'finance_account_branch_after_movement';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: enforce_finance_payment_movement_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION enforce_finance_payment_movement_account() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    movement_ok boolean;
BEGIN
    IF NEW.account_id IS NULL AND NEW.movement_id IS NULL THEN
        RETURN NEW;
    END IF;
    SELECT EXISTS(
        SELECT 1 FROM finance_account_movements m
        JOIN finance_accounts a
          ON a.company_id = m.company_id AND a.id = m.account_id
        WHERE m.company_id = NEW.company_id AND m.id = NEW.movement_id
          AND m.account_id = NEW.account_id AND m.currency = NEW.currency
          AND a.account_type = NEW.payment_method
    ) INTO movement_ok;
    IF NOT movement_ok THEN
        RAISE EXCEPTION 'finance payment movement/account relationship is invalid'
            USING ERRCODE = '23514', CONSTRAINT = 'finance_payment_movement_account';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: enforce_finance_transfer_movement_pair(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION enforce_finance_transfer_movement_pair() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    out_ok boolean;
    in_ok boolean;
BEGIN
    SELECT EXISTS(
        SELECT 1 FROM finance_account_movements m
        WHERE m.company_id = NEW.company_id AND m.id = NEW.out_movement_id
          AND m.account_id = NEW.from_account_id AND m.currency = NEW.currency
          AND m.direction = 'OUT' AND m.movement_kind = 'TRANSFER'
          AND m.source_type = 'finance_transfer' AND m.source_id = NEW.id
    ) INTO out_ok;
    SELECT EXISTS(
        SELECT 1 FROM finance_account_movements m
        WHERE m.company_id = NEW.company_id AND m.id = NEW.in_movement_id
          AND m.account_id = NEW.to_account_id AND m.currency = NEW.currency
          AND m.direction = 'IN' AND m.movement_kind = 'TRANSFER'
          AND m.source_type = 'finance_transfer' AND m.source_id = NEW.id
    ) INTO in_ok;
    IF NOT out_ok OR NOT in_ok THEN
        RAISE EXCEPTION 'finance transfer movement pair is invalid'
            USING ERRCODE = '23514', CONSTRAINT = 'finance_transfer_movement_pair';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: enforce_legislation_pack_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION enforce_legislation_pack_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF OLD.status IN ('ACTIVE','SUPERSEDED') THEN
   IF OLD.status='ACTIVE' AND NEW.status='SUPERSEDED' AND
      ROW(NEW.company_id,NEW.id,NEW.country_code,NEW.code,NEW.version,NEW.effective_from,NEW.effective_to,
          NEW.minimum_monthly_gross,NEW.sgk_daily_floor,NEW.sgk_daily_ceiling,NEW.stamp_tax_rate,NEW.source_metadata,
          NEW.supersedes_pack_id,NEW.change_reason,NEW.activated_at,NEW.created_by,NEW.created_at)
      IS NOT DISTINCT FROM
      ROW(OLD.company_id,OLD.id,OLD.country_code,OLD.code,OLD.version,OLD.effective_from,OLD.effective_to,
          OLD.minimum_monthly_gross,OLD.sgk_daily_floor,OLD.sgk_daily_ceiling,OLD.stamp_tax_rate,OLD.source_metadata,
          OLD.supersedes_pack_id,OLD.change_reason,OLD.activated_at,OLD.created_by,OLD.created_at) THEN RETURN NEW; END IF;
   RAISE EXCEPTION 'active or superseded legislation pack is immutable' USING ERRCODE='55000',CONSTRAINT='payroll_legislation_pack_immutable';
 END IF;
 RETURN NEW;
END; $$;

--
-- Name: enforce_manual_reversal_provenance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION enforce_manual_reversal_provenance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    original_type text;
    original_source text;
    original_source_id uuid;
    original_reversal_of uuid;
BEGIN
    IF NEW.reversal_of_id IS NULL OR NEW.source_type <> 'STOCK_MOVEMENT_REVERSAL' THEN
        RETURN NEW;
    END IF;

    SELECT movement_type, source_type, source_id, reversal_of_id
      INTO original_type, original_source, original_source_id, original_reversal_of
      FROM stock_movements
     WHERE company_id = NEW.company_id AND id = NEW.reversal_of_id;

    IF original_type IS NULL THEN
        -- The foreign key rejects a genuinely missing original.
        RETURN NEW;
    END IF;

    -- Genuinely manual movements are always reversible here.
    IF original_type = 'MANUAL_ADJUSTMENT' OR original_source = 'STOCK_MOVEMENT_OPERATION' THEN
        RETURN NEW;
    END IF;

    -- A reversal entry cannot itself be reversed.
    IF original_reversal_of IS NOT NULL OR original_source LIKE '%\_REVERSAL' ESCAPE '\' THEN
        RAISE EXCEPTION 'stock movement % is a reversal entry and cannot be reversed again', NEW.reversal_of_id
            USING ERRCODE = '23514';
    END IF;

    -- A movement tied to a commercial document must be undone by cancelling it.
    IF original_source_id IS NOT NULL
       AND EXISTS (SELECT 1 FROM documents d WHERE d.company_id = NEW.company_id AND d.id = original_source_id) THEN
        RAISE EXCEPTION 'document-origin stock movement % cannot be manually reversed (movement_type=%, source_type=%)',
            NEW.reversal_of_id, original_type, original_source
            USING ERRCODE = '23514';
    END IF;

    -- Otherwise (opening stock import, warehouse transfer, stock count): allow.
    RETURN NEW;
END;
$$;

--
-- Name: enforce_product_media_variant(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION enforce_product_media_variant() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.variant_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM product_variants pv
        WHERE pv.company_id = NEW.company_id
          AND pv.id = NEW.variant_id
          AND pv.product_id = NEW.product_id
    ) THEN
        RAISE EXCEPTION 'media variant does not belong to product' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: enforce_purchase_order_header_immutability(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION enforce_purchase_order_header_immutability() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        IF OLD.status <> 'DRAFT' THEN
            RAISE EXCEPTION 'non-draft purchase orders are immutable' USING ERRCODE = '55000';
        END IF;
        RETURN OLD;
    END IF;

    IF OLD.status = 'DRAFT' THEN
        RETURN NEW;
    END IF;

    IF NEW.company_id <> OLD.company_id OR
       NEW.order_no <> OLD.order_no OR
       NEW.supplier_id <> OLD.supplier_id OR
       NEW.branch_id <> OLD.branch_id OR
       NEW.warehouse_id <> OLD.warehouse_id OR
       NEW.order_date <> OLD.order_date OR
       NEW.currency <> OLD.currency OR
       NEW.over_delivery_policy <> OLD.over_delivery_policy OR
       NEW.notes <> OLD.notes OR
       NEW.total <> OLD.total OR
       NEW.created_by <> OLD.created_by OR
       NEW.created_at <> OLD.created_at OR
       NEW.version <> OLD.version + 1 OR
       (OLD.confirmed_at IS NOT NULL AND NEW.confirmed_at IS DISTINCT FROM OLD.confirmed_at) OR
       (OLD.cancelled_at IS NOT NULL AND NEW.cancelled_at IS DISTINCT FROM OLD.cancelled_at) OR
       (OLD.cancellation_reason IS NOT NULL AND NEW.cancellation_reason IS DISTINCT FROM OLD.cancellation_reason) THEN
        RAISE EXCEPTION 'confirmed purchase-order content is immutable' USING ERRCODE = '55000';
    END IF;

    -- Fulfillment projection may move in either direction while the order
    -- stays OPEN; DRAFT is never re-entered and CANCELLED is terminal.
    IF NEW.status = 'DRAFT' OR
       NEW.status NOT IN ('CONFIRMED', 'PARTIALLY_FULFILLED', 'FULFILLED', 'CANCELLED') OR
       (OLD.status = 'CANCELLED' AND NEW.status <> 'CANCELLED') THEN
        RAISE EXCEPTION 'invalid purchase-order state transition' USING ERRCODE = '55000';
    END IF;

    IF NEW.status = 'CANCELLED' AND btrim(COALESCE(NEW.cancellation_reason, '')) = '' THEN
        RAISE EXCEPTION 'cancelled purchase orders require a reason' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: enforce_purchase_order_line_immutability(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION enforce_purchase_order_line_immutability() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    order_status text;
BEGIN
    SELECT status INTO order_status
      FROM purchase_orders
     WHERE company_id = COALESCE(OLD.company_id, NEW.company_id)
       AND id = COALESCE(OLD.order_id, NEW.order_id);
    IF order_status IS NULL THEN
        RAISE EXCEPTION 'purchase-order parent is required' USING ERRCODE = '23503';
    END IF;
    IF order_status = 'DRAFT' THEN
        RETURN COALESCE(NEW, OLD);
    END IF;
    IF TG_OP = 'INSERT' OR TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'non-draft purchase-order lines are immutable' USING ERRCODE = '55000';
    END IF;
    IF NEW.company_id <> OLD.company_id OR
       NEW.order_id <> OLD.order_id OR
       NEW.line_no <> OLD.line_no OR
       NEW.line_type IS DISTINCT FROM OLD.line_type OR
       NEW.product_id <> OLD.product_id OR
       NEW.variant_id IS DISTINCT FROM OLD.variant_id OR
       NEW.warehouse_id IS DISTINCT FROM OLD.warehouse_id OR
       NEW.supplier_product_code_snapshot <> OLD.supplier_product_code_snapshot OR
       NEW.product_code_snapshot <> OLD.product_code_snapshot OR
       NEW.product_name_snapshot <> OLD.product_name_snapshot OR
       NEW.unit_code <> OLD.unit_code OR
       NEW.ordered_quantity <> OLD.ordered_quantity OR
       NEW.base_quantity <> OLD.base_quantity OR
       NEW.conversion_factor <> OLD.conversion_factor OR
       NEW.unit_price <> OLD.unit_price OR
       NEW.currency <> OLD.currency OR
       NEW.tax_snapshot IS DISTINCT FROM OLD.tax_snapshot OR
       NEW.received_quantity < 0 OR
       NEW.invoiced_quantity < 0 OR
       (NEW.line_type = 'SERVICE' AND NEW.invoiced_quantity > NEW.ordered_quantity) OR
       (NEW.line_type = 'PRODUCT' AND NEW.invoiced_quantity > NEW.received_quantity) THEN
        RAISE EXCEPTION 'confirmed purchase-order line content is immutable' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: enforce_purchase_posted_header_immutability(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION enforce_purchase_posted_header_immutability() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    old_content jsonb;
    new_content jsonb;
BEGIN
    IF TG_OP = 'DELETE' THEN
        IF OLD.status <> 'DRAFT' THEN
            RAISE EXCEPTION 'posted purchase documents are immutable' USING ERRCODE = '55000';
        END IF;
        RETURN OLD;
    END IF;

    IF OLD.status = 'CANCELLED' THEN
        RAISE EXCEPTION 'cancelled purchase documents are immutable' USING ERRCODE = '55000';
    END IF;

    IF NEW.version <> OLD.version + 1 THEN
        RAISE EXCEPTION 'purchase document version must advance exactly once' USING ERRCODE = '55000';
    END IF;

    old_content := to_jsonb(OLD) - ARRAY['status','version','cancelled_at','cancellation_reason'];
    new_content := to_jsonb(NEW) - ARRAY['status','version','cancelled_at','cancellation_reason'];
    IF OLD.status <> 'DRAFT' AND new_content IS DISTINCT FROM old_content THEN
        RAISE EXCEPTION 'posted purchase document content is immutable' USING ERRCODE = '55000';
    END IF;

    IF OLD.status = 'DRAFT' THEN
        IF NEW.status NOT IN ('DRAFT','POSTED') THEN
            RAISE EXCEPTION 'invalid purchase document state transition' USING ERRCODE = '55000';
        END IF;
        IF NEW.status = 'DRAFT' AND NEW.posted_at IS NOT NULL THEN
            RAISE EXCEPTION 'draft purchase documents cannot have posted_at' USING ERRCODE = '23514';
        END IF;
        IF NEW.status = 'POSTED' AND NEW.posted_at IS NULL THEN
            RAISE EXCEPTION 'posted purchase documents require posted_at' USING ERRCODE = '23514';
        END IF;
        IF NEW.cancelled_at IS NOT NULL OR NULLIF(btrim(COALESCE(NEW.cancellation_reason,'')), '') IS NOT NULL THEN
            RAISE EXCEPTION 'cancellation details require a cancelled document' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;

    IF OLD.status = 'POSTED' AND NEW.status NOT IN ('POSTED','CANCELLED') THEN
        RAISE EXCEPTION 'invalid purchase document state transition' USING ERRCODE = '55000';
    END IF;
    IF NEW.status = 'POSTED' AND NEW.posted_at IS NULL THEN
        RAISE EXCEPTION 'posted purchase documents require posted_at' USING ERRCODE = '23514';
    END IF;
    IF NEW.status = 'CANCELLED' THEN
        IF NEW.cancelled_at IS NULL OR NULLIF(btrim(COALESCE(NEW.cancellation_reason,'')), '') IS NULL THEN
            RAISE EXCEPTION 'cancelled purchase documents require a reason' USING ERRCODE = '23514';
        END IF;
    ELSIF NEW.cancelled_at IS DISTINCT FROM OLD.cancelled_at OR
          NEW.cancellation_reason IS DISTINCT FROM OLD.cancellation_reason THEN
        RAISE EXCEPTION 'cancellation details are immutable' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: enforce_sales_return_reason_immutability(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION enforce_sales_return_reason_immutability() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.status <> 'DRAFT' AND NEW.reason IS DISTINCT FROM OLD.reason THEN
        RAISE EXCEPTION 'posted sales return reason is immutable' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: enforce_stock_count_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION enforce_stock_count_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.state = NEW.state THEN
        RETURN NEW;
    END IF;
    IF (OLD.state = 'DRAFT' AND NEW.state = 'IN_PROGRESS') OR
       (OLD.state = 'IN_PROGRESS' AND NEW.state IN ('COUNTED', 'REVIEW', 'CANCELLED')) OR
       (OLD.state = 'COUNTED' AND NEW.state IN ('REVIEW', 'POSTED', 'CANCELLED')) OR
       (OLD.state = 'REVIEW' AND NEW.state IN ('POSTED', 'CANCELLED')) THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION 'invalid stock count state transition' USING ERRCODE = '55000';
END;
$$;

--
-- Name: enforce_transfer_state_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION enforce_transfer_state_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.state = NEW.state THEN
        RETURN NEW;
    END IF;
    IF (OLD.state = 'DRAFT' AND NEW.state IN ('REQUESTED', 'APPROVED', 'CANCELLED')) OR
       (OLD.state = 'REQUESTED' AND NEW.state IN ('APPROVED', 'CANCELLED')) OR
       (OLD.state = 'APPROVED' AND NEW.state IN ('IN_TRANSIT', 'CANCELLED')) OR
       (OLD.state = 'IN_TRANSIT' AND NEW.state IN ('PARTIALLY_RECEIVED', 'RECEIVED', 'CANCELLED')) OR
       (OLD.state = 'PARTIALLY_RECEIVED' AND NEW.state IN ('RECEIVED', 'CANCELLED')) THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION 'WAREHOUSE_TRANSFER_INVALID_STATE' USING ERRCODE = '55000';
END;
$$;

--
-- Name: ensure_company_has_system_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION ensure_company_has_system_admin() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    target_company uuid := COALESCE(NEW.company_id, OLD.company_id);
BEGIN
    IF EXISTS (SELECT 1 FROM roles WHERE company_id=target_company AND is_system)
       AND NOT EXISTS (
           SELECT 1
           FROM membership_roles mr
           JOIN roles r ON r.company_id=mr.company_id AND r.id=mr.role_id AND r.is_system
           JOIN company_memberships m ON m.company_id=mr.company_id AND m.user_id=mr.user_id AND m.is_active
           WHERE mr.company_id=target_company
       ) THEN
        RAISE EXCEPTION 'company must retain an active system administrator' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: guard_active_component_treatment_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION guard_active_component_treatment_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE pack_status text;
BEGIN
    SELECT p.status INTO pack_status
    FROM payroll_component_definitions c
    JOIN payroll_legislation_packs p ON p.company_id=c.company_id AND p.id=c.pack_id
    WHERE c.company_id=OLD.company_id AND c.id=OLD.component_definition_id;
    IF pack_status IN ('ACTIVE','SUPERSEDED') THEN
        RAISE EXCEPTION 'active or superseded legislation treatment is immutable'
            USING ERRCODE='55000',CONSTRAINT='payroll_component_treatment_immutable';
    END IF;
    RETURN COALESCE(NEW,OLD);
END; $$;

--
-- Name: guard_active_legislation_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION guard_active_legislation_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE pack_status text;
BEGIN
    IF TG_TABLE_NAME='payroll_legislation_packs' THEN pack_status:=OLD.status;
    ELSE SELECT status INTO pack_status FROM payroll_legislation_packs
         WHERE company_id=OLD.company_id AND id=OLD.pack_id; END IF;
    IF TG_OP='DELETE' OR pack_status IN ('ACTIVE','SUPERSEDED') THEN
        RAISE EXCEPTION 'active or superseded legislation is immutable' USING ERRCODE='55000',CONSTRAINT='payroll_legislation_immutable';
    END IF;
    RETURN NEW;
END; $$;

--
-- Name: guard_product_variant_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION guard_product_variant_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF (NEW.variant_code IS DISTINCT FROM OLD.variant_code
        OR NEW.variant_signature IS DISTINCT FROM OLD.variant_signature)
       AND EXISTS (SELECT 1 FROM stock_movements WHERE company_id = OLD.company_id AND variant_id = OLD.id) THEN
        RAISE EXCEPTION 'VARIANT_IDENTITY_LOCKED' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: guard_product_variant_mode(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION guard_product_variant_mode() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.variants_enabled IS DISTINCT FROM OLD.variants_enabled THEN
        IF NEW.variants_enabled AND NEW.kind::text <> 'PHYSICAL' THEN
            RAISE EXCEPTION 'VARIANT_PRODUCT_MUST_BE_PHYSICAL' USING ERRCODE = '23514';
        END IF;
        IF EXISTS (
            SELECT 1 FROM stock_movements
             WHERE company_id = NEW.company_id AND product_id = NEW.id
        ) OR EXISTS (
            SELECT 1 FROM stock_positions
             WHERE company_id = NEW.company_id AND product_id = NEW.id
               AND (physical_quantity <> 0 OR reserved_quantity <> 0)
        ) THEN
            RAISE EXCEPTION 'VARIANT_MODE_REQUIRES_EMPTY_STOCK_HISTORY' USING ERRCODE = '55000';
        END IF;
        IF NOT NEW.variants_enabled AND EXISTS (
            SELECT 1 FROM product_variants
             WHERE company_id = NEW.company_id AND product_id = NEW.id
        ) THEN
            RAISE EXCEPTION 'VARIANT_MODE_CANNOT_BE_DISABLED' USING ERRCODE = '55000';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: guard_stock_count_engine_header(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION guard_stock_count_engine_header() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.state IN ('POSTED', 'CANCELLED') AND (
        NEW.company_id IS DISTINCT FROM OLD.company_id OR NEW.id IS DISTINCT FROM OLD.id OR
        NEW.warehouse_id IS DISTINCT FROM OLD.warehouse_id OR NEW.movement_policy IS DISTINCT FROM OLD.movement_policy OR
        NEW.blind_count IS DISTINCT FROM OLD.blind_count OR NEW.scope_mode IS DISTINCT FROM OLD.scope_mode OR
        NEW.snapshot_at IS DISTINCT FROM OLD.snapshot_at OR
        NEW.start_idempotency_key IS DISTINCT FROM OLD.start_idempotency_key
    ) THEN
        RAISE EXCEPTION 'posted or cancelled stock count engine is immutable' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: guard_stock_count_engine_metadata(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION guard_stock_count_engine_metadata() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.state IN ('POSTED', 'CANCELLED') AND (
        NEW.count_no IS DISTINCT FROM OLD.count_no OR
        NEW.description IS DISTINCT FROM OLD.description
    ) THEN
        RAISE EXCEPTION 'posted or cancelled stock count metadata is immutable' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: guard_system_transit_warehouse(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION guard_system_transit_warehouse() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        IF OLD.is_system AND OLD.is_transit THEN
            RAISE EXCEPTION 'WAREHOUSE_SYSTEM' USING ERRCODE = '55000';
        END IF;
        RETURN OLD;
    END IF;

    IF TG_OP = 'UPDATE' AND OLD.is_system AND OLD.is_transit THEN
        RAISE EXCEPTION 'WAREHOUSE_SYSTEM' USING ERRCODE = '55000';
    END IF;

    IF NEW.warehouse_type = 'TRANSIT' OR NEW.is_transit OR NEW.is_system THEN
        IF COALESCE(current_setting('varyaone.allow_system_transit', true), '') <> 'on' THEN
            RAISE EXCEPTION 'WAREHOUSE_SYSTEM' USING ERRCODE = '55000';
        END IF;
        NEW.warehouse_type := 'TRANSIT';
        NEW.is_transit := true;
        NEW.is_system := true;
        NEW.is_active := true;
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: guard_transfer_reservation_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION guard_transfer_reservation_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF COALESCE(current_setting('varyaone.allow_transfer_reservation_change', true), '') <> 'on' THEN
        RAISE EXCEPTION 'TRANSFER_RESERVATION_IMMUTABLE' USING ERRCODE = '55000';
    END IF;
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'TRANSFER_RESERVATION_IMMUTABLE' USING ERRCODE = '55000';
    END IF;
    IF TG_OP = 'UPDATE' THEN
        IF NEW.company_id IS DISTINCT FROM OLD.company_id
           OR NEW.transfer_id IS DISTINCT FROM OLD.transfer_id
           OR NEW.transfer_line_id IS DISTINCT FROM OLD.transfer_line_id
           OR NEW.warehouse_id IS DISTINCT FROM OLD.warehouse_id
           OR NEW.product_id IS DISTINCT FROM OLD.product_id
           OR NEW.variant_id IS DISTINCT FROM OLD.variant_id
           OR NEW.location_id IS DISTINCT FROM OLD.location_id
           OR NEW.lot_id IS DISTINCT FROM OLD.lot_id
           OR NEW.serial_id IS DISTINCT FROM OLD.serial_id
           OR NEW.quantity IS DISTINCT FROM OLD.quantity
           OR OLD.state <> 'ACTIVE'
           OR NEW.state NOT IN ('CONSUMED', 'RELEASED')
           OR (NEW.state = 'CONSUMED' AND NEW.released_at IS NOT NULL)
           OR (NEW.state = 'RELEASED' AND NEW.consumed_at IS NOT NULL) THEN
            RAISE EXCEPTION 'TRANSFER_RESERVATION_IMMUTABLE' USING ERRCODE = '55000';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: keep_system_transit_unavailable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION keep_system_transit_unavailable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    transit boolean;
BEGIN
    SELECT is_transit AND is_system INTO transit
      FROM warehouses
     WHERE company_id = NEW.company_id AND id = NEW.warehouse_id;
    IF COALESCE(transit, false) THEN
        NEW.reserved_quantity := NEW.physical_quantity;
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: normalize_party_search_text(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION normalize_party_search_text(value text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
    SELECT regexp_replace(
        translate(
            translate(
                translate(
                    lower(replace(coalesce(value,''),'İ','I')),
                    'ığiüşöçâäàáãåéèëêîïìíñóòôõúùûýÿ',
                    'igiusocaaaaaaeeeeiiiinoooouuuyy'
                ),
                'čćďđłňńøřśšťţžźż',
                'ccddlnnorssttzzz'
            ),
            'āēīōūăĕĭŏŭæœß',
            'aeiouaeiouaos'
        ),
        '[^[:alnum:]]+',
        ' ',
        'g'
    )
$$;

--
-- Name: party_search_detail_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

