--
-- Name: party_search_party_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION party_search_party_trigger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF COALESCE(current_setting('varyaone.party_search_suppressed', true), '') = 'on' THEN
