--
-- Name: party_search_related_definition_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION party_search_related_definition_trigger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    related_id uuid := COALESCE(NEW.id, OLD.id);
    related_company_id uuid;
    item record;
BEGIN
    IF TG_TABLE_NAME = 'party_groups' THEN
        related_company_id := COALESCE(NEW.company_id, OLD.company_id);
        FOR item IN SELECT company_id, party_id FROM party_group_memberships WHERE company_id=related_company_id AND group_id=related_id LOOP
            PERFORM refresh_party_search_document(item.company_id, item.party_id);
        END LOOP;
    ELSIF TG_TABLE_NAME = 'party_tags' THEN
        related_company_id := COALESCE(NEW.company_id, OLD.company_id);
        FOR item IN SELECT company_id, party_id FROM party_tag_assignments WHERE company_id=related_company_id AND tag_id=related_id LOOP
            PERFORM refresh_party_search_document(item.company_id, item.party_id);
        END LOOP;
    ELSIF TG_TABLE_NAME = 'party_custom_field_definitions' THEN
        related_company_id := COALESCE(NEW.company_id, OLD.company_id);
        FOR item IN SELECT company_id, party_id FROM party_custom_field_values WHERE company_id=related_company_id AND definition_id=related_id LOOP
            PERFORM refresh_party_search_document(item.company_id, item.party_id);
        END LOOP;
    ELSIF TG_TABLE_NAME = 'payment_terms' THEN
        related_company_id := COALESCE(NEW.company_id, OLD.company_id);
        FOR item IN SELECT company_id, id AS party_id FROM parties WHERE company_id=related_company_id AND payment_term_id=related_id LOOP
            PERFORM refresh_party_search_document(item.company_id, item.party_id);
        END LOOP;
    ELSIF TG_TABLE_NAME = 'users' THEN
        FOR item IN SELECT company_id, id AS party_id FROM parties WHERE sales_rep_user_id=related_id LOOP
            PERFORM refresh_party_search_document(item.company_id, item.party_id);
        END LOOP;
    END IF;
    RETURN NULL;
END;
$$;

--
-- Name: populate_party_ledger_currency_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION populate_party_ledger_currency_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    company_currency char(3);
BEGIN
    SELECT c.base_currency INTO company_currency
      FROM companies c
     WHERE c.id = NEW.company_id;
    NEW.base_currency := company_currency;
    NEW.base_amount := ROUND((NEW.debit + NEW.credit) * NEW.exchange_rate, 4);
    RETURN NEW;
END;
$$;

--
-- Name: prevent_used_timesheet_reopen(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION prevent_used_timesheet_reopen() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.status='FINALIZED' AND NEW.status='DRAFT' AND EXISTS (
        SELECT 1 FROM payroll_runs r WHERE r.company_id=OLD.company_id
          AND r.timesheet_period_id=OLD.id AND r.status='FINALIZED') THEN
        RAISE EXCEPTION 'timesheet is used by finalized payroll' USING ERRCODE='55000',CONSTRAINT='timesheet_used_by_finalized_payroll';
    END IF;
    RETURN NEW;
END; $$;

--
-- Name: pricing_seed_default_currencies(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION pricing_seed_default_currencies() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
BEGIN
    INSERT INTO pricing_currencies(company_id,code,name,symbol,minor_unit,is_custom,source)
    VALUES
        (NEW.id,'TRY','Türk lirası','₺',2,false,'ISO_4217_BASELINE'),
        (NEW.id,'USD','ABD doları','$',2,false,'ISO_4217_BASELINE'),
        (NEW.id,'EUR','Euro','€',2,false,'ISO_4217_BASELINE'),
        (NEW.id,'GBP','İngiliz sterlini','£',2,false,'ISO_4217_BASELINE'),
        (NEW.id,NEW.base_currency,NEW.base_currency,'',2,NEW.base_currency NOT IN ('TRY','USD','EUR','GBP'),'COMPANY_BASE_CURRENCY')
    ON CONFLICT (company_id,code) DO NOTHING;
    RETURN NEW;
END;
$_$;

--
-- Name: refresh_document_search_vector(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION refresh_document_search_vector() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.search_vector :=
        setweight(to_tsvector('simple', coalesce(NEW.document_no, '')), 'A') ||
        setweight(to_tsvector('simple', coalesce(NEW.notes, '')), 'C');
    RETURN NEW;
END;
$$;

--
-- Name: refresh_party_search_balance(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION refresh_party_search_balance(target_company_id uuid, target_party_id uuid) RETURNS void
    LANGUAGE sql
    AS $$
    UPDATE party_search_documents d
    SET balance_search=normalize_party_search_text(COALESCE((
        SELECT SUM(e.base_signed_amount)::text
        FROM party_ledger_balance_effects e
        WHERE e.company_id=target_company_id AND e.party_id=target_party_id
    ), '0'))
    WHERE d.company_id=target_company_id AND d.party_id=target_party_id;
$$;

