--
-- Name: refresh_party_search_document(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION refresh_party_search_document(target_company_id uuid, target_party_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO party_search_documents(company_id, party_id, search_text, balance_search)
    SELECT
        p.company_id,
        p.id,
        normalize_party_search_text(concat_ws(' ',
            to_jsonb(p)::text,
            -- Index both compact and separated code forms.  This lets a
            -- search for CR-000001 find an automatically generated CR000001.
            regexp_replace(
                regexp_replace(coalesce(p.code,''), '([[:alpha:]])([[:digit:]])', '\1 \2', 'g'),
                '([[:digit:]])([[:alpha:]])', '\1 \2', 'g'
            ),
            CASE WHEN p.is_customer THEN 'müşteri' ELSE '' END,
            CASE WHEN p.is_supplier THEN 'tedarikçi' ELSE '' END,
            CASE WHEN p.kind::text = 'PERSON' THEN 'kişi' ELSE 'kurum' END,
            CASE WHEN p.is_active THEN 'aktif' ELSE 'pasif' END,
            CASE WHEN p.payment_term_id IS NULL THEN 'peşin' ELSE '' END,
            COALESCE((SELECT concat_ws(' ',pt.code,pt.name,pt.due_days::text,pt.due_days::text || ' gün')
                FROM payment_terms pt
                WHERE pt.company_id=p.company_id AND pt.id=p.payment_term_id), ''),
            COALESCE((SELECT u.display_name
                FROM users u
                WHERE u.id=p.sales_rep_user_id), ''),
            COALESCE((SELECT string_agg(to_jsonb(a)::text, ' ' ORDER BY a.id)
                FROM party_addresses a
                WHERE a.company_id=p.company_id AND a.party_id=p.id), ''),
            COALESCE((SELECT string_agg(to_jsonb(c)::text, ' ' ORDER BY c.is_primary DESC, c.id)
                FROM party_contacts c
                WHERE c.company_id=p.company_id AND c.party_id=p.id), ''),
            COALESCE((SELECT string_agg(to_jsonb(pg)::text, ' ' ORDER BY pg.id)
                FROM party_group_memberships pgm
                JOIN party_groups pg ON pg.company_id=pgm.company_id AND pg.id=pgm.group_id
                WHERE pgm.company_id=p.company_id AND pgm.party_id=p.id), ''),
            COALESCE((SELECT string_agg(to_jsonb(pt)::text, ' ' ORDER BY pt.id)
                FROM party_tag_assignments pta
                JOIN party_tags pt ON pt.company_id=pta.company_id AND pt.id=pta.tag_id
                WHERE pta.company_id=p.company_id AND pta.party_id=p.id), ''),
            COALESCE((SELECT string_agg(concat_ws(' ', to_jsonb(pd)::text, to_jsonb(pv)::text), ' ' ORDER BY pd.id)
                FROM party_custom_field_values pv
                JOIN party_custom_field_definitions pd ON pd.company_id=pv.company_id AND pd.id=pv.definition_id
                WHERE pv.company_id=p.company_id AND pv.party_id=p.id), '')
        )),
        normalize_party_search_text(COALESCE((SELECT (sum(l.debit)-sum(l.credit))::text
            FROM party_ledger_entries l
            WHERE l.company_id=p.company_id AND l.party_id=p.id AND l.currency=p.default_currency), '0'))
    FROM parties p
    WHERE p.company_id=target_company_id AND p.id=target_party_id
    ON CONFLICT (company_id, party_id) DO UPDATE
        SET search_text=excluded.search_text, balance_search=excluded.balance_search;

    DELETE FROM party_search_documents d
    WHERE d.company_id=target_company_id
      AND d.party_id=target_party_id
      AND NOT EXISTS (
          SELECT 1 FROM parties p WHERE p.company_id=d.company_id AND p.id=d.party_id
      );
END;
$$;

--
-- Name: reject_company_base_currency_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION reject_company_base_currency_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.base_currency IS DISTINCT FROM OLD.base_currency AND (
        EXISTS (SELECT 1 FROM party_ledger_entries WHERE company_id = OLD.id)
        OR EXISTS (SELECT 1 FROM finance_account_movements WHERE company_id = OLD.id)
        OR EXISTS (SELECT 1 FROM stock_movements WHERE company_id = OLD.id)
        OR EXISTS (SELECT 1 FROM documents WHERE company_id = OLD.id AND posted_at IS NOT NULL)
    ) THEN
        RAISE EXCEPTION 'company base currency is locked after posted history'
            USING ERRCODE = '55000', CONSTRAINT = 'company_base_currency_locked';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: reject_completed_idempotency_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION reject_completed_idempotency_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' AND OLD.status = 'COMPLETED' THEN
        RAISE EXCEPTION 'completed idempotency records are immutable' USING ERRCODE = '55000';
    END IF;
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    IF OLD.status = 'COMPLETED' AND (
        NEW.company_id <> OLD.company_id OR
        NEW.idempotency_key <> OLD.idempotency_key OR
        NEW.command_name <> OLD.command_name OR
        NEW.payload_sha256 <> OLD.payload_sha256 OR
        NEW.status <> OLD.status OR
        NEW.response_status IS DISTINCT FROM OLD.response_status OR
        NEW.response_body IS DISTINCT FROM OLD.response_body OR
        NEW.response_headers IS DISTINCT FROM OLD.response_headers OR
        NEW.completed_at IS DISTINCT FROM OLD.completed_at OR
        NEW.actor_user_id IS DISTINCT FROM OLD.actor_user_id OR
        NEW.trace_id IS DISTINCT FROM OLD.trace_id OR
        NEW.created_at IS DISTINCT FROM OLD.created_at
    ) THEN
        RAISE EXCEPTION 'completed idempotency records are immutable' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

