--
-- Name: reject_finalized_payroll_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION reject_finalized_payroll_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE target_company uuid; target_run uuid; locked boolean;
BEGIN
    target_company:=COALESCE(NEW.company_id,OLD.company_id);
    IF TG_TABLE_NAME='payroll_runs' THEN target_run:=COALESCE(NEW.id,OLD.id);
    ELSIF TG_TABLE_NAME='payroll_calculation_generations' THEN target_run:=COALESCE(NEW.payroll_run_id,OLD.payroll_run_id);
    ELSIF TG_TABLE_NAME='employee_payrolls' THEN target_run:=COALESCE(NEW.payroll_run_id,OLD.payroll_run_id);
    ELSE SELECT payroll_run_id INTO target_run FROM employee_payrolls
         WHERE company_id=target_company AND id=COALESCE(NEW.employee_payroll_id,OLD.employee_payroll_id); END IF;
    SELECT status='FINALIZED' INTO locked FROM payroll_runs WHERE company_id=target_company AND id=target_run;
    IF locked THEN RAISE EXCEPTION 'finalized payroll is immutable' USING ERRCODE='55000',CONSTRAINT='payroll_finalized_immutable'; END IF;
    RETURN COALESCE(NEW,OLD);
END; $$;

--
-- Name: reject_finalized_timesheet_day_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION reject_finalized_timesheet_day_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE target_company uuid; target_period uuid; locked boolean;
BEGIN
    target_company:=COALESCE(NEW.company_id,OLD.company_id); target_period:=COALESCE(NEW.period_id,OLD.period_id);
    SELECT status='FINALIZED' INTO locked FROM timesheet_periods WHERE company_id=target_company AND id=target_period;
    IF locked THEN RAISE EXCEPTION 'finalized timesheet is immutable' USING ERRCODE='55000',CONSTRAINT='timesheet_days_finalized_immutable'; END IF;
    RETURN COALESCE(NEW,OLD);
END; $$;

