CREATE FUNCTION reject_inventory_projection_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'stock position projection cannot be deleted' USING ERRCODE = '55000';
    END IF;
    IF NEW.company_id <> OLD.company_id OR NEW.warehouse_id <> OLD.warehouse_id OR
       NEW.product_id <> OLD.product_id OR NEW.variant_id IS DISTINCT FROM OLD.variant_id OR
       NEW.location_id IS DISTINCT FROM OLD.location_id OR NEW.lot_id IS DISTINCT FROM OLD.lot_id OR
       NEW.serial_id IS DISTINCT FROM OLD.serial_id THEN
        RAISE EXCEPTION 'stock position identity is immutable' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

