--
-- Name: reject_payroll_payment_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION reject_payroll_payment_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP = 'DELETE' THEN
  RAISE EXCEPTION 'bordro ödemeleri silinemez' USING ERRCODE='55000',CONSTRAINT='payroll_payments_immutable';
 END IF;
 -- Yalnızca geri alma (PAID -> REVERSED) güncellemesine izin verilir.
 IF OLD.status <> 'PAID' OR NEW.status <> 'REVERSED'
    OR NEW.company_id <> OLD.company_id OR NEW.id <> OLD.id
    OR NEW.payroll_run_id <> OLD.payroll_run_id OR NEW.account_id <> OLD.account_id
    OR NEW.amount <> OLD.amount OR NEW.payment_date <> OLD.payment_date
    OR NEW.finance_movement_id <> OLD.finance_movement_id
    OR NEW.idempotency_key <> OLD.idempotency_key OR NEW.created_by <> OLD.created_by THEN
  RAISE EXCEPTION 'kaydedilmiş bordro ödemesi yalnızca geri alınabilir' USING ERRCODE='55000',CONSTRAINT='payroll_payments_reverse_only';
 END IF;
 RETURN NEW;
END $$;

--
-- Name: reject_posted_commercial_line_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION reject_posted_commercial_line_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
    parent_table text := CASE TG_TABLE_NAME
        WHEN 'sales_quote_lines' THEN 'sales_quotes'
        WHEN 'sales_order_lines' THEN 'sales_orders'
        WHEN 'sales_dispatch_lines' THEN 'sales_dispatches'
        WHEN 'sales_invoice_lines' THEN 'sales_invoices'
        WHEN 'sales_return_lines' THEN 'sales_returns'
        ELSE ''
    END;
    parent_status text;
    document_key uuid;
BEGIN
    IF parent_table = '' THEN
        RAISE EXCEPTION 'unsupported commercial line table';
    END IF;
    document_key := COALESCE(OLD.document_id, NEW.document_id);
    EXECUTE format('SELECT status FROM %I WHERE company_id=$1 AND id=$2', parent_table)
       INTO parent_status USING COALESCE(OLD.company_id, NEW.company_id), document_key;
    IF parent_status IS NULL OR parent_status <> 'DRAFT' THEN
        RAISE EXCEPTION 'only draft commercial document lines can be changed' USING ERRCODE = '55000';
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$_$;

--
-- Name: reject_posted_count_header_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION reject_posted_count_header_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' OR (OLD.state IN ('POSTED', 'CANCELLED') AND NEW.state = OLD.state) THEN
        RAISE EXCEPTION 'posted stock count is immutable' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: reject_posted_count_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION reject_posted_count_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    count_state text;
    target_company uuid;
    target_count uuid;
BEGIN
    IF TG_OP = 'DELETE' THEN
        target_company := OLD.company_id;
        target_count := OLD.count_id;
    ELSE
        target_company := NEW.company_id;
        target_count := NEW.count_id;
    END IF;
    SELECT state INTO count_state FROM stock_counts
     WHERE company_id = target_company AND id = target_count;
    IF count_state IN ('POSTED', 'CANCELLED') THEN
        RAISE EXCEPTION 'posted stock count is immutable' USING ERRCODE = '55000';
    END IF;
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: reject_posted_document_line_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION reject_posted_document_line_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    current_status text;
BEGIN
    SELECT status INTO current_status
    FROM documents
    WHERE company_id = COALESCE(OLD.company_id, NEW.company_id)
      AND id = COALESCE(OLD.document_id, NEW.document_id);
    IF current_status IS NULL OR current_status <> 'DRAFT' THEN
        RAISE EXCEPTION 'only draft document lines can be changed' USING ERRCODE = '55000';
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$$;

