-- Name: reject_posted_document_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION reject_posted_document_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.status IN ('POSTED', 'CANCELLED') AND NEW.status = OLD.status THEN
        RAISE EXCEPTION 'posted or cancelled documents are immutable' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: reject_posted_landed_cost_line_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION reject_posted_landed_cost_line_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    parent_status text;
BEGIN
    SELECT status INTO parent_status FROM purchase_landed_costs
     WHERE company_id = COALESCE(NEW.company_id, OLD.company_id) AND id = COALESCE(NEW.landed_cost_id, OLD.landed_cost_id);
    IF parent_status IS NULL OR parent_status <> 'DRAFT' THEN
        RAISE EXCEPTION 'only draft landed cost lines can be changed' USING ERRCODE = '55000';
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$$;

--
-- Name: reject_posted_landed_cost_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION reject_posted_landed_cost_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.status <> 'DRAFT' THEN
        IF TG_OP = 'DELETE' THEN
            RAISE EXCEPTION 'only a draft landed cost can be deleted' USING ERRCODE = '55000';
        END IF;
        IF NEW.status = 'CANCELLED' AND OLD.status = 'POSTED' AND
           NEW.id = OLD.id AND NEW.amount = OLD.amount AND NEW.goods_receipt_id = OLD.goods_receipt_id THEN
            RETURN NEW; -- cancellation is the only allowed transition off POSTED
        END IF;
        RAISE EXCEPTION 'only a draft landed cost can be changed' USING ERRCODE = '55000';
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$$;

--
-- Name: reject_posted_purchase_line_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION reject_posted_purchase_line_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
    parent_table text;
    parent_key text;
    company_key text;
    parent_status text;
BEGIN
    parent_table := CASE TG_TABLE_NAME
        WHEN 'goods_receipt_lines' THEN 'goods_receipts'
        WHEN 'purchase_invoice_lines' THEN 'purchase_invoices'
        WHEN 'purchase_return_lines' THEN 'purchase_returns'
        ELSE ''
    END;
    IF parent_table = '' THEN
        RAISE EXCEPTION 'unsupported purchase line table';
    END IF;
    company_key := COALESCE(to_jsonb(OLD)->>'company_id', to_jsonb(NEW)->>'company_id');
    parent_key := COALESCE(
        to_jsonb(OLD)->>CASE TG_TABLE_NAME
            WHEN 'goods_receipt_lines' THEN 'receipt_id'
            WHEN 'purchase_invoice_lines' THEN 'invoice_id'
            ELSE 'return_id'
        END,
        to_jsonb(NEW)->>CASE TG_TABLE_NAME
            WHEN 'goods_receipt_lines' THEN 'receipt_id'
            WHEN 'purchase_invoice_lines' THEN 'invoice_id'
            ELSE 'return_id'
        END
    );
    EXECUTE format('SELECT status FROM %I WHERE company_id=$1 AND id=$2::uuid', parent_table)
       INTO parent_status USING company_key::uuid, parent_key;
    IF parent_status IS NULL OR parent_status <> 'DRAFT' THEN
        RAISE EXCEPTION 'only draft purchase document lines can be changed' USING ERRCODE = '55000';
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$_$;

