--
-- Name: reject_stock_movement_in_locked_count_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION reject_stock_movement_in_locked_count_scope() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.source_type = 'STOCK_COUNT_ENGINE' THEN
        RETURN NEW;
    END IF;
    IF EXISTS (
        SELECT 1
          FROM stock_count_engine_counts c
          JOIN stock_count_engine_scopes s
            ON s.company_id = c.company_id AND s.count_id = c.id
         WHERE c.company_id = NEW.company_id
           AND c.warehouse_id = NEW.warehouse_id
           AND c.state IN ('IN_PROGRESS', 'REVIEW')
           AND c.movement_policy = 'LOCK_SCOPE'
           AND s.product_id = NEW.product_id
           AND s.variant_id IS NOT DISTINCT FROM NEW.variant_id
           AND s.warehouse_id = NEW.warehouse_id
           AND s.location_id IS NOT DISTINCT FROM NEW.location_id
           AND s.lot_id IS NOT DISTINCT FROM NEW.lot_id
           AND s.serial_id IS NOT DISTINCT FROM NEW.serial_id
    ) THEN
        RAISE EXCEPTION 'STOCK_COUNT_SCOPE_LOCKED' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

