--
-- Name: reject_transfer_header_reroute_after_draft(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION reject_transfer_header_reroute_after_draft() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.state <> 'DRAFT' AND (
        NEW.company_id IS DISTINCT FROM OLD.company_id OR
        NEW.transfer_type IS DISTINCT FROM OLD.transfer_type OR
        NEW.source_warehouse_id IS DISTINCT FROM OLD.source_warehouse_id OR
        NEW.destination_warehouse_id IS DISTINCT FROM OLD.destination_warehouse_id OR
        NEW.transit_warehouse_id IS DISTINCT FROM OLD.transit_warehouse_id
    ) THEN
        RAISE EXCEPTION 'posted transfer routing is immutable' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: reject_transfer_line_mutation_after_request(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION reject_transfer_line_mutation_after_request() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    transfer_state text;
    target_company uuid;
    target_transfer uuid;
BEGIN
    IF TG_OP = 'DELETE' THEN
        target_company := OLD.company_id;
        target_transfer := OLD.transfer_id;
    ELSE
        target_company := NEW.company_id;
        target_transfer := NEW.transfer_id;
    END IF;
    SELECT state INTO transfer_state FROM warehouse_transfers
     WHERE company_id = target_company AND id = target_transfer;
    IF transfer_state IN ('RECEIVED', 'CANCELLED') THEN
        RAISE EXCEPTION 'posted transfer lines are immutable' USING ERRCODE = '55000';
    END IF;
    IF TG_OP = 'DELETE' THEN
        IF transfer_state <> 'DRAFT' THEN
            RAISE EXCEPTION 'posted transfer lines are immutable' USING ERRCODE = '55000';
        END IF;
        RETURN OLD;
    END IF;
    IF transfer_state <> 'DRAFT' AND (
        NEW.company_id IS DISTINCT FROM OLD.company_id OR
        NEW.transfer_id IS DISTINCT FROM OLD.transfer_id OR
        NEW.line_no IS DISTINCT FROM OLD.line_no OR
        NEW.product_id IS DISTINCT FROM OLD.product_id OR
        NEW.variant_id IS DISTINCT FROM OLD.variant_id OR
        NEW.lot_id IS DISTINCT FROM OLD.lot_id OR
        NEW.serial_id IS DISTINCT FROM OLD.serial_id OR
        NEW.source_location_id IS DISTINCT FROM OLD.source_location_id OR
        NEW.destination_location_id IS DISTINCT FROM OLD.destination_location_id OR
        NEW.quantity IS DISTINCT FROM OLD.quantity
    ) THEN
        RAISE EXCEPTION 'posted transfer line identity is immutable' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: reject_transfer_line_snapshot_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION reject_transfer_line_snapshot_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.product_code_snapshot IS NOT DISTINCT FROM OLD.product_code_snapshot
       AND NEW.product_name_snapshot IS NOT DISTINCT FROM OLD.product_name_snapshot
       AND NEW.variant_code_snapshot IS NOT DISTINCT FROM OLD.variant_code_snapshot
       AND NEW.variant_description_snapshot IS NOT DISTINCT FROM OLD.variant_description_snapshot THEN
        RETURN NEW;
    END IF;

    RAISE EXCEPTION 'transfer line display identity is immutable' USING ERRCODE = '55000';
END;
$$;

--
-- Name: reject_uncontrolled_system_transit_movement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION reject_uncontrolled_system_transit_movement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    system_transit boolean;
BEGIN
    SELECT is_transit AND is_system INTO system_transit
      FROM warehouses
     WHERE company_id = NEW.company_id AND id = NEW.warehouse_id;
    IF COALESCE(system_transit, false)
       AND NOT (
           NEW.source_type = 'WAREHOUSE_TRANSFER'
           AND NEW.movement_type IN ('TRANSFER_IN', 'TRANSFER_OUT', 'WASTE')
       ) THEN
        RAISE EXCEPTION 'WAREHOUSE_SYSTEM' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: require_active_variant_for_stock_row(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION require_active_variant_for_stock_row() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    variants_enabled boolean;
    product_kind text;
    variant_product uuid;
    variant_active boolean;
BEGIN
    SELECT p.variants_enabled, p.kind::text
      INTO variants_enabled, product_kind
      FROM products p
     WHERE p.company_id = NEW.company_id AND p.id = NEW.product_id;
    IF product_kind = 'PHYSICAL' AND variants_enabled THEN
        IF NEW.variant_id IS NULL THEN
            RAISE EXCEPTION 'VARIANT_REQUIRED' USING ERRCODE = '23514';
        END IF;
        SELECT product_id, is_active INTO variant_product, variant_active
          FROM product_variants
         WHERE company_id = NEW.company_id AND id = NEW.variant_id;
        IF variant_product IS NULL OR variant_product <> NEW.product_id THEN
            RAISE EXCEPTION 'variant does not belong to product' USING ERRCODE = '23514';
        END IF;
        IF NOT variant_active THEN
            RAISE EXCEPTION 'VARIANT_INACTIVE' USING ERRCODE = '23514';
        END IF;
    ELSIF product_kind = 'PHYSICAL' AND NOT variants_enabled AND NEW.variant_id IS NOT NULL THEN
        RAISE EXCEPTION 'variant is not enabled for product' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

