--
-- Name: set_transfer_line_identity_snapshots(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION set_transfer_line_identity_snapshots() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    product_code_value text;
    product_name_value text;
    variant_code_value text;
    variant_description_value text;
BEGIN
    SELECT p.code, p.name
      INTO product_code_value, product_name_value
      FROM products p
     WHERE p.company_id = NEW.company_id
       AND p.id = NEW.product_id;
    IF product_code_value IS NULL OR product_name_value IS NULL THEN
        RAISE EXCEPTION 'transfer line product does not exist' USING ERRCODE = '23514';
    END IF;

    NEW.product_code_snapshot := product_code_value;
    NEW.product_name_snapshot := product_name_value;
    NEW.variant_code_snapshot := '';
    NEW.variant_description_snapshot := '';

    IF NEW.variant_id IS NOT NULL THEN
        SELECT pv.variant_code,
               COALESCE(
                   NULLIF(string_agg(o.name, ' / ' ORDER BY COALESCE(pvd.position, 32767), vv.definition_id), ''),
                   pv.variant_code
               )
          INTO variant_code_value, variant_description_value
          FROM product_variants pv
          LEFT JOIN product_variant_values vv
            ON vv.company_id = pv.company_id
           AND vv.variant_id = pv.id
          LEFT JOIN variant_definition_options o
            ON o.company_id = vv.company_id
           AND o.definition_id = vv.definition_id
           AND o.id = vv.option_id
          LEFT JOIN product_variant_definitions pvd
            ON pvd.company_id = pv.company_id
           AND pvd.product_id = pv.product_id
           AND pvd.definition_id = vv.definition_id
         WHERE pv.company_id = NEW.company_id
           AND pv.id = NEW.variant_id
         GROUP BY pv.variant_code;
        IF variant_code_value IS NULL THEN
            RAISE EXCEPTION 'transfer line variant does not exist' USING ERRCODE = '23514';
        END IF;
        NEW.variant_code_snapshot := variant_code_value;
        NEW.variant_description_snapshot := COALESCE(variant_description_value, variant_code_value);
    END IF;
    RETURN NEW;
END;
$$;

