--
-- Name: tax_seed_turkey_simple_tax_definitions_for_company(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION tax_seed_turkey_simple_tax_definitions_for_company(company_uuid uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    item record;
    definition_id uuid;
BEGIN
    FOR item IN SELECT * FROM (VALUES
        ('BSMV',   'BSMV',          NULL::numeric),
        ('DAMGA',  'Damga Vergisi', NULL::numeric),
        ('DIGER',  'Diğer Vergi',   NULL::numeric),
        ('KDV_0',  'KDV %0',        0::numeric),
        ('KDV_1',  'KDV %1',        1::numeric),
        ('KDV_10', 'KDV %10',      10::numeric),
        ('KDV_20', 'KDV %20',      20::numeric),
        ('OIV',    'ÖİV',           NULL::numeric),
        ('OTV',    'ÖTV',           NULL::numeric)
    ) AS defaults(code, name, default_rate)
    LOOP
        INSERT INTO tax_definitions(id, company_id, code, name, description, source, source_reference, source_version)
        VALUES (
            gen_random_uuid(), company_uuid, item.code, item.name,
            CASE WHEN item.code LIKE 'KDV_%' THEN 'Türkiye KDV tanımı' ELSE 'Türkiye ek vergi tanımı' END,
            'TR_TAX_LOCALIZATION', 'Varya temel vergi kataloğu', '2026-01'
        )
        ON CONFLICT (company_id, code) DO NOTHING;

        IF item.default_rate IS NOT NULL THEN
            SELECT id INTO definition_id
            FROM tax_definitions
            WHERE company_id = company_uuid AND code = item.code;

            INSERT INTO tax_rates(
                id, company_id, tax_definition_id, rate, calculation_type,
                valid_from, source, source_reference, source_version
            )
            SELECT gen_random_uuid(), company_uuid, definition_id, item.default_rate, 'PERCENTAGE',
                   DATE '2023-07-10', 'TR_TAX_LOCALIZATION', 'Varya temel vergi kataloğu', '2026-01'
            WHERE NOT EXISTS (
                SELECT 1 FROM tax_rates
                WHERE company_id = company_uuid
                  AND tax_definition_id = definition_id
                  AND valid_from = DATE '2023-07-10'
            );
        END IF;
    END LOOP;
END;
$$;

--
-- Name: tax_seed_turkey_vat_catalog(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION tax_seed_turkey_vat_catalog() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM tax_seed_turkey_vat_catalog_for_company(NEW.id);
    RETURN NEW;
END;
$$;

--
-- Name: tax_seed_turkey_vat_catalog_for_company(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION tax_seed_turkey_vat_catalog_for_company(company_uuid uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    definition_id uuid;
    item record;
BEGIN
    FOR item IN SELECT * FROM (VALUES
        ('KDV_0', 'KDV %0', '0'),
        ('KDV_1', 'KDV %1', '1'),
        ('KDV_10', 'KDV %10', '10'),
        ('KDV_20', 'KDV %20', '20')
    ) AS defaults(code, name, rate)
    LOOP
        INSERT INTO tax_definitions(id, company_id, code, name, description, source, source_reference, source_version)
        VALUES (gen_random_uuid(), company_uuid, item.code, item.name,
                'Türkiye KDV varsayılanı', 'TR_TAX_LOCALIZATION', 'GİB KDV oranları', '2026-01')
        ON CONFLICT (company_id, code) DO NOTHING;

        SELECT id INTO definition_id FROM tax_definitions
        WHERE company_id = company_uuid AND code = item.code;
        IF NOT EXISTS (
            SELECT 1 FROM tax_rates
            WHERE company_id = company_uuid AND tax_definition_id = definition_id
              AND valid_from = DATE '2023-07-10'
        ) THEN
            INSERT INTO tax_rates(id, company_id, tax_definition_id, rate, valid_from, source, source_reference, source_version)
            VALUES (gen_random_uuid(), company_uuid, definition_id, item.rate::numeric, DATE '2023-07-10',
                    'TR_TAX_LOCALIZATION', 'GİB KDV oranları', '2026-01');
        END IF;
    END LOOP;
END;
$$;

