--
-- Name: validate_commercial_line_product(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION validate_commercial_line_product() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    product_kind text;
    variant_product uuid;
BEGIN
    IF NEW.product_id IS NOT NULL THEN
        SELECT kind::text INTO product_kind FROM products
         WHERE company_id=NEW.company_id AND id=NEW.product_id AND is_active;
        IF product_kind IS NULL OR
           (NEW.line_type = 'PRODUCT' AND product_kind <> 'PHYSICAL') OR
           (NEW.line_type = 'SERVICE' AND product_kind <> 'SERVICE') THEN
            RAISE EXCEPTION 'commercial line product kind does not match line type' USING ERRCODE = '23514';
        END IF;
    ELSIF NEW.line_type <> 'SERVICE' THEN
        RAISE EXCEPTION 'product line requires a product' USING ERRCODE = '23514';
    END IF;
    IF NEW.variant_id IS NOT NULL THEN
        SELECT product_id INTO variant_product FROM product_variants
         WHERE company_id=NEW.company_id AND id=NEW.variant_id AND is_active;
        IF variant_product IS NULL OR variant_product <> NEW.product_id THEN
            RAISE EXCEPTION 'commercial line variant does not belong to product' USING ERRCODE = '23514';
        END IF;
    END IF;
    IF NEW.line_type = 'PRODUCT' AND NEW.warehouse_id IS NULL THEN
        RAISE EXCEPTION 'product commercial line requires a warehouse' USING ERRCODE = '23514';
    END IF;
    IF NEW.line_type = 'SERVICE' AND NEW.warehouse_id IS NOT NULL THEN
        RAISE EXCEPTION 'service commercial line cannot have a warehouse' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: validate_document_line_variant(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION validate_document_line_variant() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    enabled boolean;
    kind text;
    variant_product uuid;
    variant_active boolean;
    stock_effect text;
BEGIN
    SELECT p.variants_enabled, p.kind::text INTO enabled, kind
      FROM products p
     WHERE p.company_id = NEW.company_id AND p.id = NEW.product_id;
    IF NEW.variant_id IS NOT NULL THEN
        SELECT product_id, is_active INTO variant_product, variant_active
          FROM product_variants
         WHERE company_id = NEW.company_id AND id = NEW.variant_id;
        IF variant_product IS NULL OR variant_product <> NEW.product_id THEN
            RAISE EXCEPTION 'variant does not belong to product' USING ERRCODE = '23514';
        END IF;
        IF NOT COALESCE(enabled, false) OR NOT COALESCE(variant_active, false) THEN
            RAISE EXCEPTION 'document line variant is inactive or not enabled' USING ERRCODE = '23514';
        END IF;
    ELSIF COALESCE(enabled, false) AND kind = 'PHYSICAL' THEN
        SELECT dt.stock_effect INTO stock_effect
          FROM documents d JOIN document_types dt ON dt.code = d.document_type_code
         WHERE d.company_id = NEW.company_id AND d.id = NEW.document_id;
        IF stock_effect IN ('IN', 'OUT') THEN
            RAISE EXCEPTION 'VARIANT_REQUIRED' USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: validate_inventory_location(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION validate_inventory_location() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    warehouse_active boolean;
    warehouse_uses_locations boolean;
    parent_active boolean;
BEGIN
    SELECT is_active, uses_locations
      INTO warehouse_active, warehouse_uses_locations
      FROM warehouses
     WHERE company_id = NEW.company_id AND id = NEW.warehouse_id;
    IF NOT COALESCE(warehouse_active, false) THEN
        RAISE EXCEPTION 'warehouse is inactive' USING ERRCODE = '23514';
    END IF;
    IF NOT COALESCE(warehouse_uses_locations, false) THEN
        RAISE EXCEPTION 'warehouse does not use locations' USING ERRCODE = '23514';
    END IF;
    IF NEW.parent_id IS NOT NULL THEN
        SELECT is_active INTO parent_active
          FROM locations
         WHERE company_id = NEW.company_id
           AND warehouse_id = NEW.warehouse_id
           AND id = NEW.parent_id;
        IF NOT COALESCE(parent_active, false) THEN
            RAISE EXCEPTION 'location parent is inactive or missing' USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: validate_inventory_movement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION validate_inventory_movement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    product_kind text;
    variant_product uuid;
    lot_product uuid;
    serial_product uuid;
    serial_status text;
    serial_warehouse uuid;
    lot_expiry date;
    expiry_policy text;
    location_warehouse uuid;
BEGIN
    SELECT kind::text INTO product_kind FROM products
     WHERE company_id = NEW.company_id AND id = NEW.product_id;
    IF product_kind IS NULL OR product_kind <> 'PHYSICAL' THEN
        RAISE EXCEPTION 'stock movement requires a physical product' USING ERRCODE = '23514';
    END IF;
    IF NEW.variant_id IS NOT NULL THEN
        SELECT product_id INTO variant_product FROM product_variants
         WHERE company_id = NEW.company_id AND id = NEW.variant_id;
        IF variant_product IS NULL OR variant_product <> NEW.product_id THEN
            RAISE EXCEPTION 'variant does not belong to product' USING ERRCODE = '23514';
        END IF;
    END IF;
    IF NEW.location_id IS NOT NULL THEN
        SELECT warehouse_id INTO location_warehouse FROM locations
         WHERE company_id = NEW.company_id AND id = NEW.location_id AND is_active;
        IF location_warehouse IS NULL OR location_warehouse <> NEW.warehouse_id THEN
            RAISE EXCEPTION 'location does not belong to warehouse' USING ERRCODE = '23514';
        END IF;
    END IF;
    IF NEW.reason_code = 'OTHER' AND btrim(NEW.reason_description) = '' THEN
        RAISE EXCEPTION 'OTHER movement reason requires a description' USING ERRCODE = '23514';
    END IF;
    IF NEW.movement_type IN ('MANUAL_ADJUSTMENT', 'DAMAGE', 'WASTE')
       AND (btrim(NEW.reason_code) = '' OR NEW.reason_code = 'SYSTEM') THEN
        RAISE EXCEPTION 'manual stock movement requires a reason code' USING ERRCODE = '23514';
    END IF;
    IF NEW.lot_id IS NOT NULL THEN
        SELECT product_id, expires_at INTO lot_product, lot_expiry FROM lots
         WHERE company_id = NEW.company_id AND id = NEW.lot_id;
        IF lot_product IS NULL OR lot_product <> NEW.product_id THEN
            RAISE EXCEPTION 'lot does not belong to product' USING ERRCODE = '23514';
        END IF;
        SELECT COALESCE(expired_lot_policy, 'BLOCK') INTO expiry_policy
          FROM inventory_company_policies WHERE company_id = NEW.company_id;
        IF lot_expiry IS NOT NULL AND lot_expiry < NEW.posted_at::date
           AND COALESCE(expiry_policy, 'BLOCK') = 'BLOCK'
           AND NOT NEW.expiry_override THEN
            RAISE EXCEPTION 'LOT_EXPIRED' USING ERRCODE = '23514';
        END IF;
        IF NEW.expiry_override AND btrim(NEW.expiry_override_reason) = '' THEN
            RAISE EXCEPTION 'expired lot override requires a reason' USING ERRCODE = '23514';
        END IF;
    END IF;
    IF NEW.serial_id IS NOT NULL THEN
        IF NEW.quantity <> 1 THEN
            RAISE EXCEPTION 'serial movement quantity must be one' USING ERRCODE = '23514';
        END IF;
        SELECT product_id, status, active_warehouse_id
          INTO serial_product, serial_status, serial_warehouse
          FROM serial_numbers
         WHERE company_id = NEW.company_id AND id = NEW.serial_id
         FOR UPDATE;
        IF serial_product IS NULL OR serial_product <> NEW.product_id THEN
            RAISE EXCEPTION 'serial does not belong to product' USING ERRCODE = '23514';
        END IF;
        IF NEW.direction = 'OUT' AND (serial_warehouse IS NULL OR serial_warehouse <> NEW.warehouse_id) THEN
            RAISE EXCEPTION 'SERIAL_NOT_AVAILABLE' USING ERRCODE = '23514';
        END IF;
        IF NEW.direction = 'IN' AND serial_warehouse IS NOT NULL THEN
            RAISE EXCEPTION 'SERIAL_ALREADY_IN_STOCK' USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: validate_price_entry_variant_target(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION validate_price_entry_variant_target() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    variant_product uuid;
BEGIN
    IF NEW.variant_id IS NULL THEN
        RETURN NEW;
    END IF;
    SELECT product_id INTO variant_product
      FROM product_variants
     WHERE company_id = NEW.company_id AND id = NEW.variant_id;
    IF variant_product IS NULL OR variant_product <> NEW.item_id THEN
        RAISE EXCEPTION 'price entry variant does not belong to item' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: validate_product_barcode_target(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION validate_product_barcode_target() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    variants_enabled boolean;
    product_kind text;
    variant_product uuid;
BEGIN
    SELECT p.variants_enabled, p.kind::text
      INTO variants_enabled, product_kind
      FROM products p
     WHERE p.company_id = NEW.company_id AND p.id = NEW.product_id;
    IF product_kind IS NULL THEN
        RAISE EXCEPTION 'product barcode product does not exist' USING ERRCODE = '23514';
    END IF;
    IF NEW.variant_id IS NOT NULL THEN
        SELECT product_id INTO variant_product
          FROM product_variants
         WHERE company_id = NEW.company_id AND id = NEW.variant_id;
        IF variant_product IS NULL OR variant_product <> NEW.product_id OR NOT variants_enabled THEN
            RAISE EXCEPTION 'variant barcode target is invalid' USING ERRCODE = '23514';
        END IF;
    ELSIF variants_enabled THEN
        RAISE EXCEPTION 'variant barcode requires a variant' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: validate_product_variant_values(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION validate_product_variant_values() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_company_id uuid;
    v_variant_id uuid;
    v_product_id uuid;
    v_variants_enabled boolean;
    v_definition_count integer;
    v_value_count integer;
    v_invalid_option boolean;
BEGIN
    v_company_id := COALESCE(NEW.company_id, OLD.company_id);
    v_variant_id := COALESCE(NEW.variant_id, OLD.variant_id);

    SELECT pv.product_id, p.variants_enabled
      INTO v_product_id, v_variants_enabled
      FROM product_variants AS pv
      JOIN products AS p
        ON p.company_id = pv.company_id
       AND p.id = pv.product_id
     WHERE pv.company_id = v_company_id
       AND pv.id = v_variant_id;
    IF v_product_id IS NULL OR NOT v_variants_enabled THEN
        RAISE EXCEPTION 'variant values require an enabled variant product' USING ERRCODE = '23514';
    END IF;

    SELECT count(*)
      INTO v_definition_count
      FROM product_variant_definitions AS pvd
     WHERE pvd.company_id = v_company_id
       AND pvd.product_id = v_product_id;
    SELECT count(*)
      INTO v_value_count
      FROM product_variant_values AS pvv
     WHERE pvv.company_id = v_company_id
       AND pvv.variant_id = v_variant_id;
    SELECT EXISTS (
        SELECT 1
          FROM product_variant_values AS pvv
         WHERE pvv.company_id = v_company_id
           AND pvv.variant_id = v_variant_id
           AND NOT EXISTS (
               SELECT 1
                 FROM product_variant_allowed_options AS pvao
                WHERE pvao.company_id = pvv.company_id
                  AND pvao.product_id = v_product_id
                  AND pvao.definition_id = pvv.definition_id
                  AND pvao.option_id = pvv.option_id
           )
    ) INTO v_invalid_option;
    IF v_definition_count <> v_value_count OR v_invalid_option THEN
        RAISE EXCEPTION 'variant values do not match product variant configuration' USING ERRCODE = '23514';
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$$;

--
-- Name: validate_transfer_discrepancy_resolution(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION validate_transfer_discrepancy_resolution() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    transfer_state text;
    line_transfer_id uuid;
    shipped numeric(24,8);
    received numeric(24,8);
    resolved numeric(24,8);
BEGIN
    -- Always acquire the parent transfer lock before the line lock. Service
    -- commands use the same order, preventing a resolution INSERT from
    -- deadlocking with receive/ship operations.
    SELECT state
      INTO transfer_state
      FROM warehouse_transfers
     WHERE company_id = NEW.company_id AND id = NEW.transfer_id
     FOR UPDATE;
    SELECT transfer_id, shipped_quantity, received_quantity
      INTO line_transfer_id, shipped, received
      FROM warehouse_transfer_lines
     WHERE company_id = NEW.company_id AND id = NEW.transfer_line_id
     FOR UPDATE;
    IF line_transfer_id IS NULL OR line_transfer_id <> NEW.transfer_id THEN
        RAISE EXCEPTION 'transfer discrepancy line does not belong to transfer' USING ERRCODE = '23514';
    END IF;
    IF transfer_state IS NULL OR transfer_state NOT IN ('IN_TRANSIT', 'PARTIALLY_RECEIVED') THEN
        RAISE EXCEPTION 'WAREHOUSE_TRANSFER_INVALID_STATE' USING ERRCODE = '55000';
    END IF;
    SELECT COALESCE(SUM(quantity), 0)
      INTO resolved
      FROM warehouse_transfer_discrepancy_resolutions
     WHERE company_id = NEW.company_id AND transfer_line_id = NEW.transfer_line_id;
    IF resolved + NEW.quantity > shipped - received THEN
        RAISE EXCEPTION 'transfer discrepancy quantity exceeds transit quantity' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: validate_transfer_endpoints(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION validate_transfer_endpoints() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.source_warehouse_id = NEW.destination_warehouse_id THEN
        RAISE EXCEPTION 'WAREHOUSE_TRANSFER_SAME_WAREHOUSE' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: validate_transfer_stock_conservation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION validate_transfer_stock_conservation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    target_transfer uuid;
    transfer_state text;
    source_warehouse uuid;
    destination_warehouse uuid;
    transit_warehouse uuid;
    line record;
    source_out numeric(24,8);
    transit_in numeric(24,8);
    transit_out numeric(24,8);
    transit_waste numeric(24,8);
    endpoint_in numeric(24,8);
BEGIN
    IF TG_TABLE_NAME = 'stock_movements' THEN
        target_transfer := NEW.transfer_id;
    ELSE
        target_transfer := NEW.id;
    END IF;
    IF target_transfer IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT state, source_warehouse_id, destination_warehouse_id, transit_warehouse_id
      INTO transfer_state, source_warehouse, destination_warehouse, transit_warehouse
      FROM warehouse_transfers
     WHERE company_id = NEW.company_id AND id = target_transfer;
    IF transfer_state IS NULL THEN
        RETURN NEW;
    END IF;

    FOR line IN
        SELECT id, shipped_quantity
          FROM warehouse_transfer_lines
         WHERE company_id = NEW.company_id AND transfer_id = target_transfer
         ORDER BY line_no
    LOOP
        SELECT
            COALESCE(SUM(quantity) FILTER (
                WHERE warehouse_id = source_warehouse AND direction = 'OUT'
                  AND movement_type = 'TRANSFER_OUT'), 0),
            COALESCE(SUM(quantity) FILTER (
                WHERE warehouse_id = transit_warehouse AND direction = 'IN'
                  AND movement_type = 'TRANSFER_IN'), 0),
            COALESCE(SUM(quantity) FILTER (
                WHERE warehouse_id = transit_warehouse AND direction = 'OUT'
                  AND movement_type = 'TRANSFER_OUT'), 0),
            COALESCE(SUM(quantity) FILTER (
                WHERE warehouse_id = transit_warehouse AND direction = 'OUT'
                  AND movement_type = 'WASTE'), 0),
            COALESCE(SUM(quantity) FILTER (
                WHERE warehouse_id IN (source_warehouse, destination_warehouse)
                  AND direction = 'IN' AND movement_type = 'TRANSFER_IN'), 0)
          INTO source_out, transit_in, transit_out, transit_waste, endpoint_in
          FROM stock_movements
         WHERE company_id = NEW.company_id
           AND source_type = 'WAREHOUSE_TRANSFER'
           AND source_id = target_transfer
           AND source_line_id = line.id;

        IF line.shipped_quantity > 0
           AND (source_out <> line.shipped_quantity OR transit_in <> line.shipped_quantity) THEN
            RAISE EXCEPTION 'WAREHOUSE_TRANSFER_STOCK_NOT_CONSERVED' USING ERRCODE = '23514';
        END IF;
        IF transit_out <> endpoint_in THEN
            RAISE EXCEPTION 'WAREHOUSE_TRANSFER_STOCK_NOT_CONSERVED' USING ERRCODE = '23514';
        END IF;
        IF transit_out + transit_waste > transit_in THEN
            RAISE EXCEPTION 'WAREHOUSE_TRANSFER_STOCK_NOT_CONSERVED' USING ERRCODE = '23514';
        END IF;
        IF transfer_state IN ('RECEIVED', 'CANCELLED')
           AND line.shipped_quantity > 0
           AND transit_out + transit_waste <> transit_in THEN
            RAISE EXCEPTION 'WAREHOUSE_TRANSFER_STOCK_NOT_CONSERVED' USING ERRCODE = '23514';
        END IF;
    END LOOP;
    RETURN NEW;
END;
$$;

--
-- Name: validate_transfer_stock_movement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION validate_transfer_stock_movement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    transfer_state text;
    source_warehouse uuid;
    destination_warehouse uuid;
    transit_warehouse uuid;
    line_transfer uuid;
    line_product uuid;
    line_variant uuid;
    line_source_location uuid;
    line_destination_location uuid;
    line_lot uuid;
    line_serial uuid;
    line_quantity numeric(24,8);
    line_shipped numeric(24,8);
    existing_quantity numeric(24,8);
    transit_out_quantity numeric(24,8);
    endpoint_in_quantity numeric(24,8);
    current_physical numeric(24,8);
    current_reserved numeric(24,8);
    position_lock_key text;
BEGIN
    IF NEW.movement_type IN ('TRANSFER_IN', 'TRANSFER_OUT')
       AND NEW.source_type <> 'WAREHOUSE_TRANSFER' THEN
        RAISE EXCEPTION 'WAREHOUSE_MOVEMENT_NOT_ALLOWED' USING ERRCODE = '23514';
    END IF;
    IF NEW.source_type <> 'WAREHOUSE_TRANSFER' THEN
        RETURN NEW;
    END IF;
    IF NEW.source_line_id IS NULL
       OR NEW.transfer_id IS DISTINCT FROM NEW.source_id
       OR NEW.transfer_line_id IS DISTINCT FROM NEW.source_line_id THEN
        RAISE EXCEPTION 'WAREHOUSE_MOVEMENT_NOT_ALLOWED' USING ERRCODE = '23514';
    END IF;

    -- All transfer commands use this lock order: aggregate, line, position.
    SELECT state, source_warehouse_id, destination_warehouse_id, transit_warehouse_id
      INTO transfer_state, source_warehouse, destination_warehouse, transit_warehouse
      FROM warehouse_transfers
     WHERE company_id = NEW.company_id AND id = NEW.transfer_id
     FOR UPDATE;
    IF transfer_state IS NULL THEN
        RAISE EXCEPTION 'WAREHOUSE_MOVEMENT_NOT_ALLOWED' USING ERRCODE = '23514';
    END IF;

    SELECT transfer_id, product_id, variant_id, source_location_id, destination_location_id, lot_id, serial_id,
           quantity, shipped_quantity
      INTO line_transfer, line_product, line_variant, line_source_location, line_destination_location, line_lot, line_serial,
           line_quantity, line_shipped
      FROM warehouse_transfer_lines
     WHERE company_id = NEW.company_id AND id = NEW.transfer_line_id
     FOR UPDATE;
    IF line_transfer IS NULL OR line_transfer <> NEW.transfer_id
       OR line_product <> NEW.product_id
       OR line_variant IS DISTINCT FROM NEW.variant_id
       OR line_lot IS DISTINCT FROM NEW.lot_id
       OR line_serial IS DISTINCT FROM NEW.serial_id THEN
        RAISE EXCEPTION 'WAREHOUSE_MOVEMENT_NOT_ALLOWED' USING ERRCODE = '23514';
    END IF;

    IF NEW.warehouse_id = source_warehouse
       AND NEW.direction = 'OUT' AND NEW.movement_type = 'TRANSFER_OUT' THEN
        IF transfer_state <> 'APPROVED'
           OR line_source_location IS DISTINCT FROM NEW.location_id THEN
            RAISE EXCEPTION 'WAREHOUSE_TRANSFER_INVALID_STATE' USING ERRCODE = '55000';
        END IF;
        SELECT COALESCE(SUM(quantity), 0)
          INTO existing_quantity
          FROM stock_movements
         WHERE company_id = NEW.company_id
           AND source_type = 'WAREHOUSE_TRANSFER'
           AND source_id = NEW.transfer_id
           AND source_line_id = NEW.transfer_line_id
           AND warehouse_id = source_warehouse
           AND direction = 'OUT'
           AND movement_type = 'TRANSFER_OUT';
        IF existing_quantity + NEW.quantity > line_quantity THEN
            RAISE EXCEPTION 'INSUFFICIENT_STOCK' USING ERRCODE = '23514';
        END IF;
    ELSIF NEW.warehouse_id = transit_warehouse
          AND NEW.direction = 'IN' AND NEW.movement_type = 'TRANSFER_IN' THEN
        IF transfer_state <> 'APPROVED' OR NEW.location_id IS NOT NULL THEN
            RAISE EXCEPTION 'WAREHOUSE_TRANSFER_INVALID_STATE' USING ERRCODE = '55000';
        END IF;
        SELECT COALESCE(SUM(quantity), 0)
          INTO existing_quantity
          FROM stock_movements
         WHERE company_id = NEW.company_id
           AND source_type = 'WAREHOUSE_TRANSFER'
           AND source_id = NEW.transfer_id
           AND source_line_id = NEW.transfer_line_id
           AND warehouse_id = transit_warehouse
           AND direction = 'IN'
           AND movement_type = 'TRANSFER_IN';
        IF existing_quantity + NEW.quantity > line_quantity THEN
            RAISE EXCEPTION 'INSUFFICIENT_STOCK' USING ERRCODE = '23514';
        END IF;
    ELSIF NEW.warehouse_id = transit_warehouse
          AND NEW.direction = 'OUT'
          AND NEW.movement_type IN ('TRANSFER_OUT', 'WASTE') THEN
        IF transfer_state NOT IN ('IN_TRANSIT', 'PARTIALLY_RECEIVED')
           OR NEW.location_id IS NOT NULL THEN
            RAISE EXCEPTION 'WAREHOUSE_TRANSFER_INVALID_STATE' USING ERRCODE = '55000';
        END IF;
        SELECT COALESCE(SUM(quantity), 0)
          INTO existing_quantity
          FROM stock_movements
         WHERE company_id = NEW.company_id
           AND source_type = 'WAREHOUSE_TRANSFER'
           AND source_id = NEW.transfer_id
           AND source_line_id = NEW.transfer_line_id
           AND warehouse_id = transit_warehouse
           AND direction = 'OUT';
        IF existing_quantity + NEW.quantity > line_shipped THEN
            RAISE EXCEPTION 'INSUFFICIENT_STOCK' USING ERRCODE = '23514';
        END IF;
    ELSIF NEW.warehouse_id IN (source_warehouse, destination_warehouse)
          AND NEW.direction = 'IN' AND NEW.movement_type = 'TRANSFER_IN' THEN
        IF transfer_state NOT IN ('IN_TRANSIT', 'PARTIALLY_RECEIVED') THEN
            RAISE EXCEPTION 'WAREHOUSE_TRANSFER_INVALID_STATE' USING ERRCODE = '55000';
        END IF;
        IF (NEW.warehouse_id = source_warehouse
              AND line_source_location IS DISTINCT FROM NEW.location_id)
           OR (NEW.warehouse_id = destination_warehouse
              AND line_destination_location IS DISTINCT FROM NEW.location_id) THEN
            RAISE EXCEPTION 'WAREHOUSE_MOVEMENT_NOT_ALLOWED' USING ERRCODE = '23514';
        END IF;
        SELECT COALESCE(SUM(quantity), 0)
          INTO transit_out_quantity
          FROM stock_movements
         WHERE company_id = NEW.company_id
           AND source_type = 'WAREHOUSE_TRANSFER'
           AND source_id = NEW.transfer_id
           AND source_line_id = NEW.transfer_line_id
           AND warehouse_id = transit_warehouse
           AND direction = 'OUT'
           AND movement_type = 'TRANSFER_OUT';
        SELECT COALESCE(SUM(quantity), 0)
          INTO endpoint_in_quantity
          FROM stock_movements
         WHERE company_id = NEW.company_id
           AND source_type = 'WAREHOUSE_TRANSFER'
           AND source_id = NEW.transfer_id
           AND source_line_id = NEW.transfer_line_id
           AND warehouse_id IN (source_warehouse, destination_warehouse)
           AND direction = 'IN'
           AND movement_type = 'TRANSFER_IN';
        IF endpoint_in_quantity + NEW.quantity > transit_out_quantity THEN
            RAISE EXCEPTION 'INSUFFICIENT_STOCK' USING ERRCODE = '23514';
        END IF;
    ELSE
        RAISE EXCEPTION 'WAREHOUSE_MOVEMENT_NOT_ALLOWED' USING ERRCODE = '23514';
    END IF;

    -- Ordinary warehouse TRANSFER_OUT consumes available stock. The transit
    -- warehouse is intentionally fully reserved, so controlled transit OUT
    -- consumes physical stock; the transfer-state and shipped-quantity checks
    -- above constrain that exception.
    IF NEW.movement_type = 'TRANSFER_OUT' AND NEW.direction = 'OUT' THEN
        position_lock_key := NEW.company_id::text || ':' || NEW.warehouse_id::text || ':' ||
            NEW.product_id::text || ':' || COALESCE(NEW.variant_id::text, '-') || ':' ||
            COALESCE(NEW.location_id::text, '-') || ':' || COALESCE(NEW.lot_id::text, '-') || ':' ||
            COALESCE(NEW.serial_id::text, '-');
        PERFORM pg_advisory_xact_lock(hashtextextended(position_lock_key, 731));
        SELECT physical_quantity, reserved_quantity
          INTO current_physical, current_reserved
          FROM stock_positions
         WHERE company_id = NEW.company_id AND warehouse_id = NEW.warehouse_id
           AND product_id = NEW.product_id
           AND variant_id IS NOT DISTINCT FROM NEW.variant_id
           AND location_id IS NOT DISTINCT FROM NEW.location_id
           AND lot_id IS NOT DISTINCT FROM NEW.lot_id
           AND serial_id IS NOT DISTINCT FROM NEW.serial_id
         FOR UPDATE;
        IF (NEW.warehouse_id = transit_warehouse
                AND COALESCE(current_physical, 0) < NEW.quantity)
           OR (NEW.warehouse_id <> transit_warehouse
                AND COALESCE(current_physical, 0) - COALESCE(current_reserved, 0) < NEW.quantity) THEN
            RAISE EXCEPTION 'INSUFFICIENT_STOCK' USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: validate_transfer_warehouses(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION validate_transfer_warehouses() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    source_ok boolean;
    destination_ok boolean;
    transit_ok boolean;
    source_active boolean;
    source_type text;
    destination_active boolean;
    destination_type text;
    transit_active boolean;
    transit_type text;
    transit_system boolean;
BEGIN
    -- Lock all referenced warehouses in a deterministic order. This keeps
    -- reciprocal transfers from deadlocking while a lifecycle update waits
    -- on the same warehouse rows.
    PERFORM 1
      FROM warehouses
     WHERE company_id = NEW.company_id
       AND id IN (NEW.source_warehouse_id, NEW.destination_warehouse_id, NEW.transit_warehouse_id)
     ORDER BY id
     FOR UPDATE;

    SELECT is_active, warehouse_type
     INTO source_active, source_type
      FROM warehouses
     WHERE company_id = NEW.company_id AND id = NEW.source_warehouse_id;
    SELECT is_active, warehouse_type
      INTO destination_active, destination_type
      FROM warehouses
     WHERE company_id = NEW.company_id AND id = NEW.destination_warehouse_id;
    SELECT is_active, warehouse_type, is_transit
      INTO transit_active, transit_type, transit_system
      FROM warehouses
     WHERE company_id = NEW.company_id AND id = NEW.transit_warehouse_id;

    source_ok := COALESCE(source_active, false) AND source_type = 'STANDARD';
    destination_ok := COALESCE(destination_active, false) AND destination_type <> 'TRANSIT';
    transit_ok := COALESCE(transit_active, false) AND transit_type = 'TRANSIT' AND COALESCE(transit_system, false);
    IF NOT source_ok OR NOT destination_ok OR NOT transit_ok THEN
        RAISE EXCEPTION 'WAREHOUSE_TRANSFER_WAREHOUSE_RULE' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: validate_warehouse_stock_movement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION validate_warehouse_stock_movement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    warehouse_type text;
    warehouse_active boolean;
    controlled_transfer boolean := false;
    original_direction text;
BEGIN
    SELECT w.warehouse_type, w.is_active
      INTO warehouse_type, warehouse_active
     FROM warehouses w
     WHERE w.company_id = NEW.company_id AND w.id = NEW.warehouse_id
     FOR UPDATE;

    IF NOT COALESCE(warehouse_active, false) THEN
        RAISE EXCEPTION 'WAREHOUSE_INACTIVE' USING ERRCODE = '23514';
    END IF;

    IF NEW.movement_type IN ('SALES_DISPATCH', 'PURCHASE_RETURN') AND NEW.direction <> 'OUT' THEN
        RAISE EXCEPTION 'invoice stock movement direction is invalid' USING ERRCODE = '23514';
    END IF;
    IF NEW.movement_type IN ('PURCHASE_RECEIPT', 'SALES_RETURN') AND NEW.direction <> 'IN' THEN
        RAISE EXCEPTION 'invoice stock movement direction is invalid' USING ERRCODE = '23514';
    END IF;
    IF NEW.movement_type IN ('TRANSFER_OUT', 'WASTE') AND NEW.direction <> 'OUT' THEN
        RAISE EXCEPTION 'warehouse outbound movement direction is invalid' USING ERRCODE = '23514';
    END IF;
    IF NEW.movement_type = 'TRANSFER_IN' AND NEW.direction <> 'IN' THEN
        RAISE EXCEPTION 'warehouse inbound movement direction is invalid' USING ERRCODE = '23514';
    END IF;

    IF NEW.source_type = 'WAREHOUSE_TRANSFER'
       AND NEW.movement_type IN ('TRANSFER_OUT', 'WASTE') THEN
        SELECT EXISTS(
            SELECT 1
              FROM warehouse_transfers t
             WHERE t.company_id = NEW.company_id
               AND t.id = NEW.source_id
               AND t.transit_warehouse_id = NEW.warehouse_id
        ) INTO controlled_transfer;
    END IF;

    IF NEW.source_type = 'WAREHOUSE_TRANSFER'
       AND NEW.movement_type = 'TRANSFER_OUT'
       AND warehouse_type = 'STANDARD' THEN
        SELECT EXISTS(
            SELECT 1
              FROM warehouse_transfers t
             WHERE t.company_id = NEW.company_id
               AND t.id = NEW.source_id
               AND t.source_warehouse_id = NEW.warehouse_id
        ) INTO controlled_transfer;
    END IF;

    IF NEW.reversal_of_id IS NOT NULL AND NEW.movement_type = 'RECONCILIATION' THEN
        SELECT m.direction
          INTO original_direction
          FROM stock_movements m
         WHERE m.company_id = NEW.company_id
           AND m.id = NEW.reversal_of_id
           AND m.warehouse_id = NEW.warehouse_id;
        controlled_transfer := controlled_transfer OR original_direction = 'IN';
    END IF;

    IF NEW.direction = 'OUT' AND warehouse_type <> 'STANDARD' AND NOT controlled_transfer THEN
        RAISE EXCEPTION 'WAREHOUSE_MOVEMENT_NOT_ALLOWED' USING ERRCODE = '23514';
    END IF;
    IF NEW.movement_type = 'TRANSFER_OUT' AND NOT controlled_transfer THEN
        RAISE EXCEPTION 'WAREHOUSE_MOVEMENT_NOT_ALLOWED' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: validate_work_schedule_day_minutes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION validate_work_schedule_day_minutes() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE computed integer;
BEGIN
    IF NOT NEW.is_workday THEN RETURN NEW; END IF;
    computed := (EXTRACT(EPOCH FROM (NEW.ends_at-NEW.starts_at))/60)::integer;
    IF NEW.ends_next_day THEN computed := computed+1440; END IF;
    computed := computed-NEW.break_minutes;
    IF computed<=0 OR computed<>NEW.planned_minutes THEN
        RAISE EXCEPTION 'planned minutes do not match schedule times' USING ERRCODE='23514',CONSTRAINT='work_schedule_day_minutes_match';
    END IF;
    RETURN NEW;
END; $$;

