    CONSTRAINT command_idempotency_records_check1 CHECK (((status <> 'COMPLETED'::text) OR ((response_status IS NOT NULL) AND (response_body IS NOT NULL)))),
    CONSTRAINT command_idempotency_records_command_name_check CHECK ((command_name ~ '^[a-z][a-z0-9_.:-]{1,127}$'::text)),
    CONSTRAINT command_idempotency_records_idempotency_key_check CHECK (((btrim(idempotency_key) <> ''::text) AND (length(idempotency_key) <= 255))),
    CONSTRAINT command_idempotency_records_payload_sha256_check CHECK ((payload_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT command_idempotency_records_response_headers_check CHECK ((jsonb_typeof(response_headers) = 'object'::text)),
    CONSTRAINT command_idempotency_records_response_status_check CHECK (((response_status IS NULL) OR ((response_status >= 100) AND (response_status <= 599)))),
    CONSTRAINT command_idempotency_records_status_check CHECK ((status = ANY (ARRAY['IN_PROGRESS'::text, 'COMPLETED'::text, 'FAILED'::text])))
);

