    CONSTRAINT documents_discount_total_check CHECK ((discount_total >= (0)::numeric)),
    CONSTRAINT documents_document_no_check CHECK ((btrim(document_no) <> ''::text)),
    CONSTRAINT documents_exchange_rate_check CHECK ((exchange_rate > (0)::numeric)),
    CONSTRAINT documents_grand_total_check CHECK ((grand_total >= (0)::numeric)),
    CONSTRAINT documents_status_check CHECK ((status = ANY (ARRAY['DRAFT'::text, 'POSTED'::text, 'CANCELLED'::text]))),
    CONSTRAINT documents_subtotal_check CHECK ((subtotal >= (0)::numeric)),
