    CONSTRAINT party_ledger_base_amount_check CHECK ((((base_amount IS NULL) AND (base_currency IS NULL)) OR ((base_amount IS NOT NULL) AND (base_currency IS NOT NULL) AND (base_amount > (0)::numeric)))),
    CONSTRAINT party_ledger_base_currency_check CHECK (((base_currency IS NULL) OR (((base_currency)::text = upper((base_currency)::text)) AND (base_currency ~ '^[A-Z]{3}$'::text)))),
    CONSTRAINT party_ledger_entries_credit_check CHECK ((credit >= (0)::numeric)),
    CONSTRAINT party_ledger_entries_currency_check CHECK (((currency)::text = upper((currency)::text))),
    CONSTRAINT party_ledger_entries_debit_check CHECK ((debit >= (0)::numeric)),
    CONSTRAINT party_ledger_entries_description_check CHECK ((btrim(description) <> ''::text)),
    CONSTRAINT party_ledger_entries_entry_type_check CHECK ((entry_type ~ '^[A-Z][A-Z0-9_]{1,63}$'::text)),
    CONSTRAINT party_ledger_entries_exchange_rate_check CHECK ((exchange_rate > (0)::numeric)),
