--
-- Name: party_ledger_balance_effects; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW party_ledger_balance_effects AS
 SELECT l.company_id,
    l.id,
    l.party_id,
    l.currency,
    l.entry_type,
    l.source_type,
    l.source_id,
    l.description,
    l.debit,
    l.credit,
    l.exchange_rate,
    l.base_amount,
    (l.debit - l.credit) AS signed_amount,
        CASE
            WHEN ((l.base_amount IS NOT NULL) AND (COALESCE(l.base_currency, c.base_currency) = c.base_currency)) THEN
            CASE
                WHEN (l.debit > (0)::numeric) THEN l.base_amount
                ELSE (- l.base_amount)
            END
            ELSE round(((l.debit - l.credit) * l.exchange_rate), 4)
        END AS base_signed_amount,
    c.base_currency,
    l.document_date,
    l.posted_at,
    l.reversal_of_id,
    l.actor_user_id,
    l.snapshot
   FROM (party_ledger_entries l
     JOIN companies c ON ((c.id = l.company_id)));

