--
-- Name: stock_movements; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE stock_movements (
    id uuid NOT NULL,
    company_id uuid NOT NULL,
    warehouse_id uuid NOT NULL,
    location_id uuid,
    product_id uuid NOT NULL,
    variant_id uuid,
    lot_id uuid,
    serial_id uuid,
    movement_type text NOT NULL,
    direction text NOT NULL,
    quantity numeric(24,8) NOT NULL,
    quantity_delta numeric(24,8) GENERATED ALWAYS AS (
CASE
    WHEN (direction = 'IN'::text) THEN quantity
    ELSE (- quantity)
END) STORED,
    unit_cost numeric(24,8),
    currency character(3),
    reason_code text DEFAULT 'SYSTEM'::text NOT NULL,
    reason_description text DEFAULT ''::text NOT NULL,
    source_type text NOT NULL,
    source_id uuid NOT NULL,
    source_line_id uuid,
    idempotency_key text NOT NULL,
    payload_hash bytea NOT NULL,
    reversal_of_id uuid,
    expiry_override boolean DEFAULT false NOT NULL,
    expiry_override_reason text DEFAULT ''::text NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    actor_user_id uuid,
    posted_at timestamp with time zone DEFAULT now() NOT NULL,
    transfer_id uuid,
    transfer_line_id uuid,
    count_id uuid,
    count_line_id uuid,
    operation_id uuid,
    exchange_rate_snapshot numeric(24,8) DEFAULT 1 NOT NULL,
    CONSTRAINT stock_movements_check CHECK (((reason_code <> 'OTHER'::text) OR (btrim(reason_description) <> ''::text))),
    CONSTRAINT stock_movements_check1 CHECK (((NOT expiry_override) OR (btrim(expiry_override_reason) <> ''::text))),
    CONSTRAINT stock_movements_check2 CHECK (((reversal_of_id IS NULL) OR (reversal_of_id <> id))),
    CONSTRAINT stock_movements_count_line_pair_check CHECK (((count_id IS NULL) = (count_line_id IS NULL))),
    CONSTRAINT stock_movements_currency_check CHECK (((currency IS NULL) OR (((currency)::text = upper((currency)::text)) AND (currency ~ '^[A-Z]{3}$'::text)))),
    CONSTRAINT stock_movements_direction_check CHECK ((direction = ANY (ARRAY['IN'::text, 'OUT'::text]))),
    CONSTRAINT stock_movements_exchange_rate_snapshot_check CHECK ((exchange_rate_snapshot > (0)::numeric)),
    CONSTRAINT stock_movements_idempotency_key_check CHECK ((btrim(idempotency_key) <> ''::text)),
    CONSTRAINT stock_movements_metadata_check CHECK ((jsonb_typeof(metadata) = 'object'::text)),
    CONSTRAINT stock_movements_movement_type_check CHECK ((movement_type = ANY (ARRAY['PURCHASE_RECEIPT'::text, 'SALES_DISPATCH'::text, 'SALES_RETURN'::text, 'PURCHASE_RETURN'::text, 'TRANSFER_OUT'::text, 'TRANSFER_IN'::text, 'COUNT_ADJUSTMENT'::text, 'MANUAL_ADJUSTMENT'::text, 'DAMAGE'::text, 'WASTE'::text, 'RECONCILIATION'::text]))),
    CONSTRAINT stock_movements_operation_source_check CHECK (((operation_id IS NULL) OR (source_type = 'STOCK_MOVEMENT_OPERATION'::text))),
    CONSTRAINT stock_movements_payload_hash_check CHECK ((octet_length(payload_hash) = 32)),
    CONSTRAINT stock_movements_quantity_check CHECK ((quantity > (0)::numeric)),
    CONSTRAINT stock_movements_source_type_check CHECK ((btrim(source_type) <> ''::text)),
    CONSTRAINT stock_movements_transfer_line_pair_check CHECK (((transfer_id IS NULL) = (transfer_line_id IS NULL))),
    CONSTRAINT stock_movements_unit_cost_check CHECK (((unit_cost IS NULL) OR (unit_cost >= (0)::numeric)))
);

