--
--

--
-- Company-isolation RLS for the typed sales documents. In the pre-squash
-- history these tables were created with CREATE TABLE ... (LIKE sales_quotes
-- INCLUDING ...), so the static CompanyScopedTables() parser never saw their
-- company_id column and 000147_row_level_security omitted them. The squashed
-- baseline emits their columns literally, so close the gap here. Same
-- transparent policy shape as every other company-scoped table.
--
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'sales_orders','sales_order_lines',
    'sales_dispatches','sales_dispatch_lines',
    'sales_invoices','sales_invoice_lines',
    'sales_returns','sales_return_lines',
    'sales_quote_lines'
  ] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format($p$
      CREATE POLICY company_isolation ON %I
        USING (
          company_id IS NULL
          OR current_setting('varyaone.company_id', true) IS NULL
          OR current_setting('varyaone.company_id', true) = ''
          OR company_id::text = current_setting('varyaone.company_id', true)
        )
        WITH CHECK (
          company_id IS NULL
          OR current_setting('varyaone.company_id', true) IS NULL
          OR current_setting('varyaone.company_id', true) = ''
          OR company_id::text = current_setting('varyaone.company_id', true)
        )$p$, t);
  END LOOP;
END
$$;
